964	            conflicted_files: conflictedFiles,
965	            details: continueResult.stderr ?? "",
966	          });
967	          continue;
968	        }
969	      } else {
970	        spawnSync("git", ["-C", workspaceRoot, "rebase", "--abort"], { env, encoding: "utf-8" });
971	        emit({
972	          type: "workspace_pr_recovery_rebase_failed",
973	          task_id: taskId,
974	          feature_id: featureId,
975	          conflicted_files: conflictedFiles,
976	          details: rebaseResult.stderr ?? "",
977	        });
978	        continue;
979	      }
980	    }
981	
982	    const pushResult = spawnSync(
983	      "git",
984	      ["-C", workspaceRoot, "push", "--force-with-lease", "origin", taskBranch],
985	      { env, encoding: "utf-8" },
986	    );
987	
