/**
 * Handoff Trigger (T9) — fires after the Auto-Done Writer marks the last task done.
 *
 * Steps:
 *   1. Read all task YAMLs for the feature and collect completed task metadata.
 *   2. Generate docs/features/{featureId}/handoffs/handoff.md.
 *   3. Commit handoff.md to the feature branch and push.
 *   4. Promote draft PR to ready-for-review (or create if missing).
 *   5. Write handoff_pr_url, transition feature_status/current_stage in status.yaml.
 *   6. Commit and push status.yaml changes.
 *   7. Notify operator via SLACK_WEBHOOK_URL (if set).
 *   8. Emit feature_handoff_triggered and handoff_pr_opened events.
 */

import process from "node:process";
import { execSync, spawnSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { buildGitEnv } from "../git-env.js";
import {
  featureBranchName,
  featuresRoot,
  statusYamlAbsPath,
  statusYamlRelPath,
  TASKS_DIR,
} from "../paths.js";
import { curlJson } from "../utils/curl-json.js";
import type { Task } from "../types/task.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface HandoffTriggerOpts {
  workspaceRoot: string;
  featureId: string;
  /** Feature branch base branch (e.g. "main"). */
  baseBranch: string;
  /** GitHub personal access token for PR creation. */
  githubToken: string;
  /** GitHub owner extracted from management repo SSH URL. */
  repoOwner: string;
  /** GitHub repo name extracted from management repo SSH URL. */
  repoName: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

export interface HandoffTriggerResult {
  /** Error string if the operation failed; undefined on success. */
  error?: string;
  /** URL of the opened feature branch PR. */
  prUrl?: string;
}

interface StatusYaml {
  feature_status?: string;
  current_stage?: string;
  handoff_pr_url?: string | null;
  stages?: {
    handoff?: {
      review_status?: string;
      pr_url?: string | null;
      [key: string]: unknown;
    };
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function execGit(
  cmd: string,
  env: NodeJS.ProcessEnv,
  cwd: string,
): string {
  return execSync(cmd, {
    cwd,
    env,
    encoding: "utf-8",
    stdio: "pipe",
    timeout: 60_000,
  }).trim();
}

/**
 * Read all task YAMLs for a feature directory.
 * Returns an empty array if the tasks directory does not exist.
 */
function readAllTasks(workspaceRoot: string, featureId: string): Task[] {
  const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
  let files: string[] = [];
  try {
    files = readdirSync(tasksDir).filter((f) => /^T\d+\.yaml$/.test(f));
  } catch {
    return [];
  }
  const tasks: Task[] = [];
  for (const file of files) {
    try {
      tasks.push(parseYaml(readFileSync(join(tasksDir, file), "utf-8")) as Task);
    } catch {
      /* skip unreadable files */
    }
  }
  return tasks;
}

/**
 * Read product-spec.md for the feature and extract a brief summary.
 * Returns a placeholder if the file is missing or unreadable.
 */
function readProductSpecSummary(workspaceRoot: string, featureId: string): string {
  const specPath = join(featuresRoot(workspaceRoot), featureId, "product-spec.md");
  if (!existsSync(specPath)) return "_No product spec found._";
  try {
    const content = readFileSync(specPath, "utf-8");
    // Extract first non-empty paragraph after the first heading.
    const lines = content.split("\n");
    let inContent = false;
    const summaryLines: string[] = [];
    for (const line of lines) {
      if (!inContent && line.startsWith("#")) { inContent = true; continue; }
      if (!inContent) continue;
      if (line.trim() === "" && summaryLines.length > 0) break;
      if (line.trim() !== "") summaryLines.push(line.trim());
    }
    return summaryLines.length > 0 ? summaryLines.join(" ") : "_See product spec for details._";
  } catch {
    return "_Error reading product spec._";
  }
}

/**
 * Aggregate files changed across all task PRs using the GitHub Compare API.
 * Returns a markdown list; falls back to a placeholder when no PRs are available.
 */
async function fetchFilesChanged(
  tasks: Task[],
  githubToken: string,
  repoOwner: string,
  repoName: string,
): Promise<string> {
  const fileSet = new Set<string>();
  for (const task of tasks) {
    const prUrl = task.pr?.url;
    if (!prUrl) continue;
    const prMatch = /\/pull\/(\d+)$/.exec(prUrl);
    if (!prMatch) continue;
    const prNumber = prMatch[1];
    try {
      const files = curlJson([
        "-s",
        "-H", `Authorization: token ${githubToken}`,
        "-H", "Accept: application/vnd.github+json",
        `https://api.github.com/repos/${repoOwner}/${repoName}/pulls/${prNumber}/files`,
      ]) as Array<{ filename: string }>;
      if (Array.isArray(files)) {
        for (const f of files) {
          if (f.filename) fileSet.add(f.filename);
        }
      }
    } catch {
      /* non-fatal — skip this PR's files */
    }
  }
  if (fileSet.size === 0) return "_No PR file data available._";
  return [...fileSet].sort().map((f) => `- \`${f}\``).join("\n");
}

/**
 * Extract reviewer notes from the last reviewer_complete log entry (if any).
 */
function extractReviewerNotes(task: Task): string {
  const entry = [...task.log].reverse().find((e) => e.action === "reviewer_complete");
  return entry?.note ? String(entry.note) : "—";
}

/**
 * Generate the handoff document markdown from task data.
 */
async function generateHandoffDoc(
  opts: HandoffTriggerOpts,
  tasks: Task[],
  featureTitle: string,
): Promise<string> {
  const { workspaceRoot, featureId, githubToken, repoOwner, repoName } = opts;

  const summary = readProductSpecSummary(workspaceRoot, featureId);

  // Tasks Completed table
  const taskRows = tasks
    .filter((t) => t.status === "done")
    .map((t) => {
      const prUrl = t.pr?.url ? `[PR](${t.pr.url})` : "—";
      const notes = extractReviewerNotes(t);
      return `| ${t.id} — ${t.title} | ${prUrl} | ${notes} |`;
    })
    .join("\n");

  // Files changed
  const filesChanged = await fetchFilesChanged(tasks, githubToken, repoOwner, repoName);

  // Audit trail
  const auditRows = tasks
    .flatMap((t) =>
      t.log.map((entry) => ({
        action: `${t.id}: ${entry.action}`,
        actor: entry.by,
        at: entry.at,
      })),
    )
    .sort((a, b) => a.at.localeCompare(b.at))
    .map((e) => `| ${e.action} | ${e.actor} | ${e.at} |`)
    .join("\n");

  // Cancelled tasks (follow-up items)
  const cancelledTasks = tasks.filter((t) => t.status === "cancelled");
  const followUp = cancelledTasks.length > 0
    ? cancelledTasks.map((t) => `- ${t.id} — ${t.title} (cancelled)`).join("\n")
    : "_None identified._";

  return [
    `# Handoff — ${featureTitle}`,
    "",
    "## Summary",
    summary,
    "",
    "## Tasks Completed",
    "| Task | PR | Reviewer Notes |",
    "|---|---|---|",
    taskRows || "| — | — | — |",
    "",
    "## Deviations from Technical Design",
    "_See reviewer notes in Tasks Completed table above._",
    "",
    "## Files Changed",
    filesChanged,
    "",
    "## Follow-up Items",
    followUp,
    "",
    "## Audit Trail",
    "| Action | Actor | Timestamp |",
    "|---|---|---|",
    auditRows || "| — | — | — |",
  ].join("\n");
}

/**
 * Promote the feature branch PR from draft to ready-for-review.
 *
 * Primary path: read `handoff_pr_url` from status.yaml, extract the PR number,
 * call PATCH to mark `draft: false`.
 *
 * Safety net: if `handoff_pr_url` is null or the PATCH returns no html_url,
 * fall back to searching for an open PR by head branch, then creating one fresh.
 */
function promoteOrCreateFeaturePr(opts: {
  featureId: string;
  featureBranch: string;
  baseBranch: string;
  githubToken: string;
  repoOwner: string;
  repoName: string;
  existingPrUrl: string | null | undefined;
  title: string;
  body: string;
}): { prUrl: string; alreadyExisted: boolean } {
  const { featureBranch, baseBranch, githubToken, repoOwner, repoName, existingPrUrl, title, body } = opts;

  // Primary path — convert stored draft PR to ready-for-review
  if (existingPrUrl) {
    const prMatch = /\/pull\/(\d+)$/.exec(existingPrUrl);
    if (prMatch) {
      const prNumber = prMatch[1];
      const patchUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls/${prNumber}`;
      const patched = curlJson([
        "-s", "-X", "PATCH",
        "-H", `Authorization: token ${githubToken}`,
        "-H", "Accept: application/vnd.github+json",
        "-H", "Content-Type: application/json",
        "-d", JSON.stringify({ draft: false }),
        patchUrl,
      ]) as { html_url?: string };

      if (patched.html_url) {
        return { prUrl: patched.html_url, alreadyExisted: true };
      }
    }
  }

  // Safety net — search for existing open PR by head branch
  const encodedHead = encodeURIComponent(`${repoOwner}:${featureBranch}`);
  const listUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls?head=${encodedHead}&state=open`;
  const existing = curlJson([
    "-s",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    listUrl,
  ]) as Array<{ html_url: string }>;

  if (Array.isArray(existing) && existing.length > 0) {
    return { prUrl: existing[0].html_url, alreadyExisted: true };
  }

  // Last resort — create a fresh non-draft PR
  const createUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls`;
  const created = curlJson([
    "-s", "-X", "POST",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    "-H", "Content-Type: application/json",
    "-d", JSON.stringify({ title, body, head: featureBranch, base: baseBranch }),
    createUrl,
  ]) as { html_url?: string };

  if (!created.html_url) {
    throw new Error(`GitHub API PR creation failed: ${JSON.stringify(created)}`);
  }

  return { prUrl: created.html_url, alreadyExisted: false };
}

/**
 * Post a Slack notification for the handoff.
 */
async function postHandoffSlack(
  opts: HandoffTriggerOpts,
  featureTitle: string,
  prUrl: string,
  webhookUrl: string,
): Promise<void> {
  const payload = {
    text: `[Handoff] Feature ${opts.featureId} is ready for review`,
    blocks: [
      {
        type: "header",
        text: { type: "plain_text", text: `✅ Feature handoff: ${featureTitle}` },
      },
      {
        type: "section",
        fields: [
          { type: "mrkdwn", text: `*Feature:*\n${opts.featureId}` },
          { type: "mrkdwn", text: `*Handoff PR:*\n<${prUrl}|View PR>` },
        ],
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: "_All tasks are complete. The handoff document has been generated and a PR is open for review._",
        },
      },
    ],
  };
  const resp = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!resp.ok) {
    throw new Error(`Slack webhook returned ${resp.status}: ${await resp.text()}`);
  }
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Fire the Handoff Trigger for a feature whose last task was just marked done.
 *
 * Non-throwing: returns an error string on failure so the caller can decide
 * how to surface the error.
 */
export async function fireHandoffTrigger(
  opts: HandoffTriggerOpts,
): Promise<HandoffTriggerResult> {
  const {
    workspaceRoot,
    featureId,
    baseBranch,
    githubToken,
    repoOwner,
    repoName,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    emit,
  } = opts;

  const featureBranch = featureBranchName(featureId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  emit({ type: "feature_handoff_triggered", feature_id: featureId });

  // ── Step 1: Checkout feature branch ──────────────────────────────────────
  try {
    execGit("git fetch origin", env, workspaceRoot);
    execGit(
      `git checkout -B "${featureBranch}" "origin/${featureBranch}"`,
      env,
      workspaceRoot,
    );
  } catch (e) {
    return { error: `Failed to checkout feature branch: ${String(e)}` };
  }

  // ── Step 2: Read all task YAMLs ───────────────────────────────────────────
  const tasks = readAllTasks(workspaceRoot, featureId);
  if (tasks.length === 0) {
    return { error: `No task YAMLs found for feature "${featureId}"` };
  }

  // Read feature title from status.yaml (or fall back to featureId)
  let featureTitle = featureId;
  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
  let statusYaml: StatusYaml = {};
  if (existsSync(statusPath)) {
    try {
      statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
      if (typeof statusYaml.title === "string") featureTitle = statusYaml.title;
    } catch {
      /* use featureId as fallback */
    }
  }

  // ── Step 3: Generate handoff.md ───────────────────────────────────────────
  let handoffContent: string;
  try {
    handoffContent = await generateHandoffDoc(opts, tasks, featureTitle);
  } catch (e) {
    return { error: `Failed to generate handoff document: ${String(e)}` };
  }

  const handoffsDir = join(featuresRoot(workspaceRoot), featureId, "handoffs");
  const handoffPath = join(handoffsDir, "handoff.md");
  const handoffRelPath = join("docs", "features", featureId, "handoffs", "handoff.md");

  try {
    mkdirSync(handoffsDir, { recursive: true });
    writeFileSync(handoffPath, handoffContent, "utf-8");
  } catch (e) {
    return { error: `Failed to write handoff.md: ${String(e)}` };
  }

  // ── Step 4: Commit handoff.md ─────────────────────────────────────────────
  try {
    execGit(`git add "${handoffRelPath}"`, env, workspaceRoot);
    execGit(
      `git commit -m "chore(${featureId}): generate handoff document"`,
      env,
      workspaceRoot,
    );
  } catch (e) {
    const stderr = (e as { stderr?: string }).stderr ?? String(e);
    if (!stderr.includes("nothing to commit")) {
      return { error: `Failed to commit handoff.md: ${String(e)}` };
    }
  }

  // ── Step 5: Promote draft PR to ready-for-review (or create if missing) ─────
  let prUrl: string;
  let alreadyExisted: boolean;
  try {
    const prResult = promoteOrCreateFeaturePr({
      featureId,
      featureBranch,
      baseBranch,
      githubToken,
      repoOwner,
      repoName,
      existingPrUrl: statusYaml.handoff_pr_url ?? null,
      title: `feat(${featureId}): handoff — ${featureTitle}`,
      body: `## Feature Handoff\n\nFeature: \`${featureId}\`\nBranch: \`${featureBranch}\`\n\nAll tasks are complete. This PR merges the feature branch into \`${baseBranch}\`.`,
    });
    prUrl = prResult.prUrl;
    alreadyExisted = prResult.alreadyExisted;
  } catch (e) {
    return { error: `Failed to promote/open feature PR: ${String(e)}` };
  }

  emit({
    type: "handoff_pr_opened",
    feature_id: featureId,
    pr_url: prUrl,
    already_existed: alreadyExisted,
  });

  // ── Step 6: Update status.yaml ────────────────────────────────────────────
  try {
    statusYaml.handoff_pr_url = prUrl;
    statusYaml.feature_status = "in_handoff";
    statusYaml.current_stage = "handoff";
    if (statusYaml.stages?.handoff) {
      statusYaml.stages.handoff.pr_url = prUrl;
    }
    writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");

    const statusRelPath = statusYamlRelPath(featureId);
    execGit(`git add "${statusRelPath}"`, env, workspaceRoot);
    try {
      execGit(
        `git commit -m "chore(${featureId}): transition to in_handoff; record handoff PR"`,
        env,
        workspaceRoot,
      );
    } catch (e) {
      const stderr = (e as { stderr?: string }).stderr ?? String(e);
      if (!stderr.includes("nothing to commit")) throw e;
    }
  } catch (e) {
    // Non-fatal — PR is already open; log but don't fail.
    emit({
      type: "handoff_status_yaml_update_failed",
      feature_id: featureId,
      details: String(e),
    });
  }

  // ── Step 7: Push feature branch ───────────────────────────────────────────
  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", featureBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    emit({
      type: "handoff_push_failed",
      feature_id: featureId,
      details: push.stderr,
    });
    // Non-fatal — the handoff doc and PR are still created.
  }

  // ── Step 8: Slack notification ────────────────────────────────────────────
  const webhookUrl = process.env["SLACK_WEBHOOK_URL"];
  if (webhookUrl) {
    try {
      await postHandoffSlack(opts, featureTitle, prUrl, webhookUrl);
    } catch (e) {
      emit({
        type: "handoff_slack_failed",
        feature_id: featureId,
        error: String(e),
      });
    }
  } else {
    emit({ type: "handoff_slack_skipped", feature_id: featureId });
  }

  return { prUrl };
}

tool_use_result.stdout:
/**
 * Handoff Trigger (T9) — fires after the Auto-Done Writer marks the last task done.
 *
 * Steps:
 *   1. Read all task YAMLs for the feature and collect completed task metadata.
 *   2. Generate docs/features/{featureId}/handoffs/handoff.md.
 *   3. Commit handoff.md to the feature branch and push.
 *   4. Promote draft PR to ready-for-review (or create if missing).
 *   5. Write handoff_pr_url, transition feature_status/current_stage in status.yaml.
 *   6. Commit and push status.yaml changes.
 *   7. Notify operator via SLACK_WEBHOOK_URL (if set).
 *   8. Emit feature_handoff_triggered and handoff_pr_opened events.
 */

import process from "node:process";
import { execSync, spawnSync } from "node:child_process";
import {
  existsSync,
  mkdirSync,
  readdirSync,
  readFileSync,
  writeFileSync,
} from "node:fs";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { buildGitEnv } from "../git-env.js";
import {
  featureBranchName,
  featuresRoot,
  statusYamlAbsPath,
  statusYamlRelPath,
  TASKS_DIR,
} from "../paths.js";
import { curlJson } from "../utils/curl-json.js";
import type { Task } from "../types/task.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface HandoffTriggerOpts {
  workspaceRoot: string;
  featureId: string;
  /** Feature branch base branch (e.g. "main"). */
  baseBranch: string;
  /** GitHub personal access token for PR creation. */
  githubToken: string;
  /** GitHub owner extracted from management repo SSH URL. */
  repoOwner: string;
  /** GitHub repo name extracted from management repo SSH URL. */
  repoName: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

export interface HandoffTriggerResult {
  /** Error string if the operation failed; undefined on success. */
  error?: string;
  /** URL of the opened feature branch PR. */
  prUrl?: string;
}

interface StatusYaml {
  feature_status?: string;
  current_stage?: string;
  handoff_pr_url?: string | null;
  stages?: {
    handoff?: {
      review_status?: string;
      pr_url?: string | null;
      [key: string]: unknown;
    };
    [key: string]: unknown;
  };
  [key: string]: unknown;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function execGit(
  cmd: string,
  env: NodeJS.ProcessEnv,
  cwd: string,
): string {
  return execSync(cmd, {
    cwd,
    env,
    encoding: "utf-8",
    stdio: "pipe",
    timeout: 60_000,
  }).trim();
}

/**
 * Read all task YAMLs for a feature directory.
 * Returns an empty array if the tasks directory does not exist.
 */
function readAllTasks(workspaceRoot: string, featureId: string): Task[] {
  const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
  let files: string[] = [];
  try {
    files = readdirSync(tasksDir).filter((f) => /^T\d+\.yaml$/.test(f));
  } catch {
    return [];
  }
  const tasks: Task[] = [];
  for (const file of files) {
    try {
      tasks.push(parseYaml(readFileSync(join(tasksDir, file), "utf-8")) as Task);
    } catch {
      /* skip unreadable files */
    }
  }
  return tasks;
}

/**
 * Read product-spec.md for the feature and extract a brief summary.
 * Returns a placeholder if the file is missing or unreadable.
 */
function readProductSpecSummary(workspaceRoot: string, featureId: string): string {
  const specPath = join(featuresRoot(workspaceRoot), featureId, "product-spec.md");
  if (!existsSync(specPath)) return "_No product spec found._";
  try {
    const content = readFileSync(specPath, "utf-8");
    // Extract first non-empty paragraph after the first heading.
    const lines = content.split("\n");
    let inContent = false;
    const summaryLines: string[] = [];
    for (const line of lines) {
      if (!inContent && line.startsWith("#")) { inContent = true; continue; }
      if (!inContent) continue;
      if (line.trim() === "" && summaryLines.length > 0) break;
      if (line.trim() !== "") summaryLines.push(line.trim());
    }
    return summaryLines.length > 0 ? summaryLines.join(" ") : "_See product spec for details._";
  } catch {
    return "_Error reading product spec._";
  }
}

/**
 * Aggregate files changed across all task PRs using the GitHub Compare API.
 * Returns a markdown list; falls back to a placeholder when no PRs are available.
 */
async function fetchFilesChanged(
  tasks: Task[],
  githubToken: string,
  repoOwner: string,
  repoName: string,
): Promise<string> {
  const fileSet = new Set<string>();
  for (const task of tasks) {
    const prUrl = task.pr?.url;
    if (!prUrl) continue;
    const prMatch = /\/pull\/(\d+)$/.exec(prUrl);
    if (!prMatch) continue;
    const prNumber = prMatch[1];
    try {
      const files = curlJson([
        "-s",
        "-H", `Authorization: token ${githubToken}`,
        "-H", "Accept: application/vnd.github+json",
        `https://api.github.com/repos/${repoOwner}/${repoName}/pulls/${prNumber}/files`,
      ]) as Array<{ filename: string }>;
      if (Array.isArray(files)) {
        for (const f of files) {
          if (f.filename) fileSet.add(f.filename);
        }
      }
    } catch {
      /* non-fatal — skip this PR's files */
    }
  }
  if (fileSet.size === 0) return "_No PR file data available._";
  return [...fileSet].sort().map((f) => `- \`${f}\``).join("\n");
}

/**
 * Extract reviewer notes from the last reviewer_complete log entry (if any).
 */
function extractReviewerNotes(task: Task): string {
  const entry = [...task.log].reverse().find((e) => e.action === "reviewer_complete");
  return entry?.note ? String(entry.note) : "—";
}

/**
 * Generate the handoff document markdown from task data.
 */
async function generateHandoffDoc(
  opts: HandoffTriggerOpts,
  tasks: Task[],
  featureTitle: string,
): Promise<string> {
  const { workspaceRoot, featureId, githubToken, repoOwner, repoName } = opts;

  const summary = readProductSpecSummary(workspaceRoot, featureId);

  // Tasks Completed table
  const taskRows = tasks
    .filter((t) => t.status === "done")
    .map((t) => {
      const prUrl = t.pr?.url ? `[PR](${t.pr.url})` : "—";
      const notes = extractReviewerNotes(t);
      return `| ${t.id} — ${t.title} | ${prUrl} | ${notes} |`;
    })
    .join("\n");

  // Files changed
  const filesChanged = await fetchFilesChanged(tasks, githubToken, repoOwner, repoName);

  // Audit trail
  const auditRows = tasks
    .flatMap((t) =>
      t.log.map((entry) => ({
        action: `${t.id}: ${entry.action}`,
        actor: entry.by,
        at: entry.at,
      })),
    )
    .sort((a, b) => a.at.localeCompare(b.at))
    .map((e) => `| ${e.action} | ${e.actor} | ${e.at} |`)
    .join("\n");

  // Cancelled tasks (follow-up items)
  const cancelledTasks = tasks.filter((t) => t.status === "cancelled");
  const followUp = cancelledTasks.length > 0
    ? cancelledTasks.map((t) => `- ${t.id} — ${t.title} (cancelled)`).join("\n")
    : "_None identified._";

  return [
    `# Handoff — ${featureTitle}`,
    "",
    "## Summary",
    summary,
    "",
    "## Tasks Completed",
    "| Task | PR | Reviewer Notes |",
    "|---|---|---|",
    taskRows || "| — | — | — |",
    "",
    "## Deviations from Technical Design",
    "_See reviewer notes in Tasks Completed table above._",
    "",
    "## Files Changed",
    filesChanged,
    "",
    "## Follow-up Items",
    followUp,
    "",
    "## Audit Trail",
    "| Action | Actor | Timestamp |",
    "|---|---|---|",
    auditRows || "| — | — | — |",
  ].join("\n");
}

/**
 * Promote the feature branch PR from draft to ready-for-review.
 *
 * Primary path: read `handoff_pr_url` from status.yaml, extract the PR number,
 * call PATCH to mark `draft: false`.
 *
 * Safety net: if `handoff_pr_url` is null or the PATCH returns no html_url,
 * fall back to searching for an open PR by head branch, then creating one fresh.
 */
function promoteOrCreateFeaturePr(opts: {
  featureId: string;
  featureBranch: string;
  baseBranch: string;
  githubToken: string;
  repoOwner: string;
  repoName: string;
  existingPrUrl: string | null | undefined;
  title: string;
  body: string;
}): { prUrl: string; alreadyExisted: boolean } {
  const { featureBranch, baseBranch, githubToken, repoOwner, repoName, existingPrUrl, title, body } = opts;

  // Primary path — convert stored draft PR to ready-for-review
  if (existingPrUrl) {
    const prMatch = /\/pull\/(\d+)$/.exec(existingPrUrl);
    if (prMatch) {
      const prNumber = prMatch[1];
      const patchUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls/${prNumber}`;
      const patched = curlJson([
        "-s", "-X", "PATCH",
        "-H", `Authorization: token ${githubToken}`,
        "-H", "Accept: application/vnd.github+json",
        "-H", "Content-Type: application/json",
        "-d", JSON.stringify({ draft: false }),
        patchUrl,
      ]) as { html_url?: string };

      if (patched.html_url) {
        return { prUrl: patched.html_url, alreadyExisted: true };
      }
    }
  }

  // Safety net — search for existing open PR by head branch
  const encodedHead = encodeURIComponent(`${repoOwner}:${featureBranch}`);
  const listUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls?head=${encodedHead}&state=open`;
  const existing = curlJson([
    "-s",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    listUrl,
  ]) as Array<{ html_url: string }>;

  if (Array.isArray(existing) && existing.length > 0) {
    return { prUrl: existing[0].html_url, alreadyExisted: true };
  }

  // Last resort — create a fresh non-draft PR
  const createUrl = `https://api.github.com/repos/${repoOwner}/${repoName}/pulls`;
  const created = curlJson([
    "-s", "-X", "POST",
    "-H", `Authorization: token ${githubToken}`,
    "-H", "Accept: application/vnd.github+json",
    "-H", "Content-Type: application/json",
    "-d", JSON.stringify({ title, body, head: featureBranch, base: baseBranch }),
    createUrl,
  ]) as { html_url?: string };

  if (!created.html_url) {
    throw new Error(`GitHub API PR creation failed: ${JSON.stringify(created)}`);
  }

  return { prUrl: created.html_url, alreadyExisted: false };
}

/**
 * Post a Slack notification for the handoff.
 */
async function postHandoffSlack(
  opts: HandoffTriggerOpts,
  featureTitle: string,
  prUrl: string,
  webhookUrl: string,
): Promise<void> {
  const payload = {
    text: `[Handoff] Feature ${opts.featureId} is ready for review`,
    blocks: [
      {
        type: "header",
        text: { type: "plain_text", text: `✅ Feature handoff: ${featureTitle}` },
      },
      {
        type: "section",
        fields: [
          { type: "mrkdwn", text: `*Feature:*\n${opts.featureId}` },
          { type: "mrkdwn", text: `*Handoff PR:*\n<${prUrl}|View PR>` },
        ],
      },
      {
        type: "section",
        text: {
          type: "mrkdwn",
          text: "_All tasks are complete. The handoff document has been generated and a PR is open for review._",
        },
      },
    ],
  };
  const resp = await fetch(webhookUrl, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });
  if (!resp.ok) {
    throw new Error(`Slack webhook returned ${resp.status}: ${await resp.text()}`);
  }
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Fire the Handoff Trigger for a feature whose last task was just marked done.
 *
 * Non-throwing: returns an error string on failure so the caller can decide
 * how to surface the error.
 */
export async function fireHandoffTrigger(
  opts: HandoffTriggerOpts,
): Promise<HandoffTriggerResult> {
  const {
    workspaceRoot,
    featureId,
    baseBranch,
    githubToken,
    repoOwner,
    repoName,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    emit,
  } = opts;

  const featureBranch = featureBranchName(featureId);
  const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });

  emit({ type: "feature_handoff_triggered", feature_id: featureId });

  // ── Step 1: Checkout feature branch ──────────────────────────────────────
  try {
    execGit("git fetch origin", env, workspaceRoot);
    execGit(
      `git checkout -B "${featureBranch}" "origin/${featureBranch}"`,
      env,
      workspaceRoot,
    );
  } catch (e) {
    return { error: `Failed to checkout feature branch: ${String(e)}` };
  }

  // ── Step 2: Read all task YAMLs ───────────────────────────────────────────
  const tasks = readAllTasks(workspaceRoot, featureId);
  if (tasks.length === 0) {
    return { error: `No task YAMLs found for feature "${featureId}"` };
  }

  // Read feature title from status.yaml (or fall back to featureId)
  let featureTitle = featureId;
  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
  let statusYaml: StatusYaml = {};
  if (existsSync(statusPath)) {
    try {
      statusYaml = parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
      if (typeof statusYaml.title === "string") featureTitle = statusYaml.title;
    } catch {
      /* use featureId as fallback */
    }
  }

  // ── Step 3: Generate handoff.md ───────────────────────────────────────────
  let handoffContent: string;
  try {
    handoffContent = await generateHandoffDoc(opts, tasks, featureTitle);
  } catch (e) {
    return { error: `Failed to generate handoff document: ${String(e)}` };
  }

  const handoffsDir = join(featuresRoot(workspaceRoot), featureId, "handoffs");
  const handoffPath = join(handoffsDir, "handoff.md");
  const handoffRelPath = join("docs", "features", featureId, "handoffs", "handoff.md");

  try {
    mkdirSync(handoffsDir, { recursive: true });
    writeFileSync(handoffPath, handoffContent, "utf-8");
  } catch (e) {
    return { error: `Failed to write handoff.md: ${String(e)}` };
  }

  // ── Step 4: Commit handoff.md ─────────────────────────────────────────────
  try {
    execGit(`git add "${handoffRelPath}"`, env, workspaceRoot);
    execGit(
      `git commit -m "chore(${featureId}): generate handoff document"`,
      env,
      workspaceRoot,
    );
  } catch (e) {
    const stderr = (e as { stderr?: string }).stderr ?? String(e);
    if (!stderr.includes("nothing to commit")) {
      return { error: `Failed to commit handoff.md: ${String(e)}` };
    }
  }

  // ── Step 5: Promote draft PR to ready-for-review (or create if missing) ─────
  let prUrl: string;
  let alreadyExisted: boolean;
  try {
    const prResult = promoteOrCreateFeaturePr({
      featureId,
      featureBranch,
      baseBranch,
      githubToken,
      repoOwner,
      repoName,
      existingPrUrl: statusYaml.handoff_pr_url ?? null,
      title: `feat(${featureId}): handoff — ${featureTitle}`,
      body: `## Feature Handoff\n\nFeature: \`${featureId}\`\nBranch: \`${featureBranch}\`\n\nAll tasks are complete. This PR merges the feature branch into \`${baseBranch}\`.`,
    });
    prUrl = prResult.prUrl;
    alreadyExisted = prResult.alreadyExisted;
  } catch (e) {
    return { error: `Failed to promote/open feature PR: ${String(e)}` };
  }

  emit({
    type: "handoff_pr_opened",
    feature_id: featureId,
    pr_url: prUrl,
    already_existed: alreadyExisted,
  });

  // ── Step 6: Update status.yaml ────────────────────────────────────────────
  try {
    statusYaml.handoff_pr_url = prUrl;
    statusYaml.feature_status = "in_handoff";
    statusYaml.current_stage = "handoff";
    if (statusYaml.stages?.handoff) {
      statusYaml.stages.handoff.pr_url = prUrl;
    }
    writeFileSync(statusPath, yamlStringify(statusYaml), "utf-8");

    const statusRelPath = statusYamlRelPath(featureId);
    execGit(`git add "${statusRelPath}"`, env, workspaceRoot);
    try {
      execGit(
        `git commit -m "chore(${featureId}): transition to in_handoff; record handoff PR"`,
        env,
        workspaceRoot,
      );
    } catch (e) {
      const stderr = (e as { stderr?: string }).stderr ?? String(e);
      if (!stderr.includes("nothing to commit")) throw e;
    }
  } catch (e) {
    // Non-fatal — PR is already open; log but don't fail.
    emit({
      type: "handoff_status_yaml_update_failed",
      feature_id: featureId,
      details: String(e),
    });
  }

  // ── Step 7: Push feature branch ───────────────────────────────────────────
  const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", featureBranch], {
    env,
    encoding: "utf-8",
  });
  if (push.status !== 0) {
    emit({
      type: "handoff_push_failed",
      feature_id: featureId,
      details: push.stderr,
    });
    // Non-fatal — the handoff doc and PR are still created.
  }

  // ── Step 8: Slack notification ────────────────────────────────────────────
  const webhookUrl = process.env["SLACK_WEBHOOK_URL"];
  if (webhookUrl) {
    try {
      await postHandoffSlack(opts, featureTitle, prUrl, webhookUrl);
    } catch (e) {
      emit({
        type: "handoff_slack_failed",
        feature_id: featureId,
        error: String(e),
      });
    }
  } else {
    emit({ type: "handoff_slack_skipped", feature_id: featureId });
  }

  return { prUrl };
}

/**
 * Orchestrator main entry point.
 *
 * Lifecycle:
 *   bootstrap (once) → polling loop:
 *     pull workspaces → eligibility → claim → briefing → adapter.run →
 *     side-effects → sleep → repeat
 *
 * idle_sleep_seconds controls loop behaviour (read from agent.yaml):
 *   0   → single-shot mode: one cycle then exit
 *   >0  → continuous: loops indefinitely, sleeping idle_sleep_seconds between cycles
 *
 * Exit codes:
 *   0  normal exit
 *   2  agent.yaml invalid
 *   3  git clone/pull failed (bootstrap only)
 *   4  unexpected fatal error
 */

import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import { execSync, spawn } from "node:child_process";
import { randomUUID } from "node:crypto";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { runBootstrap } from "./bootstrap/bootstrap.js";
import { resolveSSHKey } from "./resolve-ssh-key.js";
import { workspaceYamlPath, taskYamlAbsPath, taskYamlRelPath, taskBranchName, featureBranchName } from "./paths.js";
import { runFeatureBranchLifecycle } from "./feature-branch/lifecycle-manager.js";
import { findEligibleTasks, findFixableTasks, findReviewableTasks } from "./eligibility/match.js";
import { claimTask } from "./claim/claim-task.js";
import { claimFixTask } from "./claim/claim-fix-task.js";
import { openWorkspacePr } from "./claim/open-workspace-pr.js";
import type { Task, TaskLogEntry } from "./types/task.js";
import { generateBriefing } from "./briefing/agent-context.js";
import { generateFixBriefing, extractPrUrlFromTask } from "./briefing/fix-briefing.js";
import { fetchRagContext } from "./bootstrap/fetch-rag-context.js";
import { resolveModel } from "./config/resolve-model-policy.js";
import { parseModelOverrides } from "./config/parse-model-overrides.js";
import {
  resolveRepoLocalPath,
  resolveRepoBaseBranch,
  resolveRepoGitUrl,
  loadWorkspaceModelPolicy,
  parseManagementRepoCoords,
} from "./config/workspace-config.js";
import { pullWorkspaces } from "./poll/pull-workspaces.js";
import { runAgentLoop, type CycleOutcome } from "./poll/agent-loop.js";
import { runReapLoop } from "./poll/reap-loop.js";
import { checkInReviewPrs } from "./poll/check-in-review-prs.js";
import { handleMergeConflicts } from "./pr-response/auto-rebase.js";
import { dispatchReviewer } from "./pr-response/dispatch-reviewer.js";
import { handleMergedPrs, handleWorkspacePrRecoveries } from "./poll/handle-merged-prs.js";
import type { ExecutorPortInput } from "@workflow/runtime-abi";
import { buildGitEnv } from "./git-env.js";
import { mutateTaskYaml } from "./side-effects/mutate-task-yaml.js";
import { createLocalSubprocessProfile } from "./profiles/local-subprocess.js";
import { createLocalDockerProfile } from "./profiles/local-docker.js";
import type { RuntimePorts } from "./runtime-ports.js";
import { SubProcessAdapter } from "./adapters/executor/subprocess.js";
import { InMemoryBrokerAdapter } from "./adapters/broker/in-memory.js";

// ── Helpers ───────────────────────────────────────────────────────────────────

/**
 * Returns an invokeClaudeForResolution function that pins Claude to a specific model.
 * Passed to all conflict-resolution handlers so they respect workspace model_policy
 * instead of defaulting to whatever the Claude CLI ships with.
 */
function makeConflictResolver(
  model: string,
  maxTurns = 10,
): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
  return (prompt, cwd, env) =>
    new Promise((resolve) => {
      const child = spawn(
        "claude",
        [
          "-p", prompt,
          "--model", model,
          "--max-turns", String(maxTurns),
          "--output-format", "stream-json",
          "--verbose",
          "--dangerously-skip-permissions",
        ],
        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
      );
      child.stdout.pipe(process.stdout);
      child.stderr.pipe(process.stderr);
      child.on("close", (code) => resolve(code === 0));
      child.on("error", () => resolve(false));
    });
}

function requireEnv(name: string): string {
  const val = process.env[name];
  if (!val) throw new Error(`Required environment variable ${name} is not set`);
  return val;
}

function extractRepoName(url: string): string {
  const match = /\/([^/]+?)(?:\.git)?$/.exec(url);
  return match?.[1] ?? url;
}

/** Emit a structured JSON event via the profile's EventEmitterPort. */
function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
  return (event: Record<string, unknown>) => {
    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
    ports.emitter.emit(type ?? "event", data);
  };
}

function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
  const task = parseYaml(
    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
  ) as { repo: string };
  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
  return task.repo;
}

interface TaskContext {
  taskRepoRoot: string;
  taskRepoUrl: string;
  taskBaseBranch: string;
  implementationModel: string;
}

function resolveTaskContext(
  workspaceLocalPath: string,
  featureId: string,
  task: Task,
): TaskContext {
  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);

  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
  let taskModelOverrides = {};
  try {
    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
  } catch { /* non-fatal */ }

  const implementationModel = resolveModel(
    workspaceModelPolicy,
    taskModelOverrides,
    "implementation",
    task.id,
  );

  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
}

/**
 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
 * Commits and pushes to the task branch. Throws on error.
 */
function writeRagPreFlight(
  workspaceRoot: string,
  featureId: string,
  taskId: string,
  taskBranch: string,
  gitAuthorEmail: string,
  gitAuthorName: string,
  sshKeyPath: string | undefined,
  ragPreFlight: { query: string; injected: boolean; summary: string },
): void {
  const now = new Date().toISOString();
  const entry: TaskLogEntry = {
    action: "rag_pre_flight",
    by: gitAuthorEmail,
    at: now,
    rag_context_injected: ragPreFlight.injected,
    rag_summary: ragPreFlight.summary,
    rag_query: ragPreFlight.query,
    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
  };

  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
  const relPath = taskYamlRelPath(featureId, taskId);
  const gitOpts = {
    cwd: workspaceRoot,
    encoding: "utf-8" as const,
    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
    timeout: 30_000,
    stdio: "pipe" as const,
  };

  // Anchor to the task branch tip before reading/writing — same pattern as
  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
  // the task branch, but an explicit anchor makes this function self-contained.
  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);

  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
  task.log.push(entry);
  writeFileSync(yamlPath, yamlStringify(task), "utf-8");

  execSync(`git add "${relPath}"`, gitOpts);
  execSync(
    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
    gitOpts,
  );
  execSync(`git push origin "${taskBranch}"`, gitOpts);
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main(): Promise<number> {
  let agentYamlPath: string;
  let workflowLocalPath: string;
  let workspacesRoot: string;
  let gitAuthorEmail: string;

  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
  const bootstrapEmit = (event: Record<string, unknown>) => {
    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
  };

  try {
    agentYamlPath = requireEnv("AGENT_YAML_PATH");
    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
    workspacesRoot = requireEnv("WORKSPACES_ROOT");
    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
  } catch (e) {
    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
    return 4;
  }

  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;

  const sshResolution = resolveSSHKey(process.env);
  const sshKeyPath = sshResolution.sshKeyPath;

  // ── Create the runtime profile ────────────────────────────────────────────────
  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
  // new infra is added without core changes.
  //   local-subprocess (default) — executor + in-process broker in one container
  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
    runtimeProfile === "local-docker"
      ? createLocalDockerProfile({
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
        })
      : createLocalSubprocessProfile({
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
        });

  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
  const brokerPort = await ports.broker.start();

  const emit = makeEmit(ports);
  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });

  if (sshResolution.warned) {
    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
  }

  const bootstrapResult = await runBootstrap({
    agentYamlPath,
    workflowLocalPath,
    workflowUrl: process.env.WORKFLOW_URL,
    workspacesRoot,
    sshKeyPath,
  });

  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;

  const config = bootstrapResult.config!;
  const githubToken = process.env.GITHUB_TOKEN ?? "";
  if (!githubToken) emit({ type: "warn_no_github_token" });

  // ── Feature Branch Lifecycle Manager (T8) ────────────────────────────────────
  // Runs once at startup — creates or syncs feature/{featureId} on each watched
  // workspace before the main dispatch loop begins.
  for (const watchUrl of config.watches) {
    const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
    if (!existsSync(workspaceLocalPath)) continue;
    try {
      const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
      runFeatureBranchLifecycle({
        workspaceRoot: workspaceLocalPath,
        baseBranch: mgmtCoords.baseBranch,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        emit,
      });
    } catch (e) {
      emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
    }
  }

  let lastPrPollAt: number | null = null;
  // Local counter for local-docker mode — tracks how many executor containers are
  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
  let dockerInFlight = 0;

  async function buildAndSubmitExecutor(opts: {
    task: Task;
    featureId: string;
    workspaceId: string;
    taskRepoUrl: string;
    taskBranch: string;
    taskRepoRoot: string;
    implementationModel: string;
    briefingPath: string;
    resultPath: string;
    workspaceLocalPath: string;
  }) {
    const { task, featureId, workspaceId, taskRepoUrl, taskBranch, taskRepoRoot,
            implementationModel, briefingPath, resultPath, workspaceLocalPath } = opts;

    const nonce = randomUUID();
    const callbackUrl = ports.broker.getCallbackUrl() ?? "";

    const execInput: ExecutorPortInput = {
      taskId: task.id,
      featureId,
      workspaceId,
      taskRepoUrl,
      taskRepoBranch: taskBranch,
      taskRepoPath: taskRepoRoot,
      briefingPath,
      resultPath,
      budgetTokens: config.budget.max_tokens_per_task,
      implementationModel,
      sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
      githubToken,
      callbackUrl,
      nonce,
    };

    const extraEnv: Record<string, string> = {
      WORKSPACE_ROOT: workspaceLocalPath,
      TASK_BRANCH: taskBranch,
      GIT_AUTHOR_EMAIL: gitAuthorEmail,
      GIT_AUTHOR_NAME: gitAuthorName,
      WORKFLOW_LOCAL_PATH: workflowLocalPath,
      MAX_TURNS: String(config.budget.max_iterations),
      LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
      ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
      ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
        ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
        : {}),
    };

    const adapter =
      runtimeProfile === "local-docker"
        ? new (await import("./adapters/executor/docker-run.js")).DockerRunAdapter({
            broker: ports.broker,
            extraEnv,
          })
        : new SubProcessAdapter({
            broker: ports.broker,
            extraEnv,
          });

    return adapter.submit(execInput);
  }

  async function runOneCycle(): Promise<CycleOutcome> {
    // In local-subprocess mode all repos share the same container filesystem.
    // If an executor is running, skip impl repo pulls — syncRepo would switch
    // the shared working tree to the base branch and hard-reset it, destroying
    // any uncommitted work the executor has in flight.
    const execInFlight =
      runtimeProfile === "local-subprocess"
        ? (ports.broker as InMemoryBrokerAdapter).registrySize() > 0
        : false;

    const pullResults = pullWorkspaces({
      watchUrls: config.watches,
      sshKeyPath,
      workspacesRoot,
      workflowUrl: process.env.WORKFLOW_URL,
      workflowLocalPath,
      skipImplRepoPull: execInFlight,
      emit,
    });

    const haltedUrls = new Set(
      pullResults
        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
        .map((r) => r.url),
    );

    let outcome: CycleOutcome = "idle";
    const pulledWorkspaceRoots: string[] = [];

    // ── Subprocess concurrency guard + task dispatch ──────────────────────────
    // In local-subprocess mode all repos share the same container filesystem.
    // Two concurrent subprocesses can race on git checkouts in the same repo.
    // Wrap the dispatch loop in a labeled block so we can break out of it
    // (skipping to PR poll + reap) when a subprocess is already in-flight.
    dispatchBlock: {
      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;

      if (runtimeProfile === "local-subprocess") {
        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
        if (inFlight >= maxConcurrent) {
          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
          break dispatchBlock;
        }
      } else if (runtimeProfile === "local-docker") {
        if (dockerInFlight >= maxConcurrent) {
          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
          break dispatchBlock;
        }
      }

    outerLoop:
    for (const watchUrl of config.watches) {
      if (haltedUrls.has(watchUrl)) continue;

      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
      pulledWorkspaceRoots.push(workspaceLocalPath);

      if (!existsSync(workspaceLocalPath)) {
        emit({ type: "workspace_not_found", workspace_url: watchUrl });
        continue;
      }

      let eligibleTasks;
      try {
        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
      } catch (e) {
        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
        continue;
      }

      if (eligibleTasks.length === 0) {
        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
        continue;
      }

      for (const { task, featureId } of eligibleTasks) {
        const claimResult = await claimTask({
          workspaceRoot: workspaceLocalPath,
          taskId: task.id,
          featureId,
          gitAuthorEmail,
          gitAuthorName,
          sshKeyPath,
          jitterMaxSeconds: config.jitter_max_seconds,
        });

        const taskBranch = taskBranchName(featureId, task.id);

        if (!claimResult.won) {
          if (claimResult.reason !== "branch_blocked_recovery") {
            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
            continue;
          }
          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
        } else {
          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
        }

        // ── Open management-repo PR ───────────────────────────────────────────
        if (githubToken) {
          try {
            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
            await openWorkspacePr({
              workspaceRoot: workspaceLocalPath,
              featureId,
              taskId: task.id,
              branch: taskBranch,
              // Task PRs target the feature branch so all task changes collect
              // there before the Handoff Trigger merges to the base branch (T8).
              baseBranch: featureBranchName(featureId),
              githubToken,
              repoOwner: mgmtCoords.owner,
              repoName: mgmtCoords.repo,
              gitAuthorEmail,
              gitAuthorName,
              sshKeyPath,
            });
            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
          } catch (e) {
            const stderr = (e as { stderr?: Buffer | string }).stderr;
            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
          }
        }

        // ── Resolve model + task repo ────────────────────────────────────────
        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
          resolveTaskContext(workspaceLocalPath, featureId, task);

        // ── RAG pre-flight ───────────────────────────────────────────────────
        const mcpRagUrl = process.env.MCP_RAG_URL;
        const workspaceYaml = parseYaml(
          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
        ) as { workspace_id: string };
        const ragQuery = `${task.title} ${featureId}`;
        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);

        try {
          writeRagPreFlight(
            workspaceLocalPath,
            featureId,
            task.id,
            taskBranch,
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
          );
        } catch (e) {
          const details = String(e);
          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
          mutateTaskYaml({
            workspaceRoot: workspaceLocalPath,
            featureId,
            taskId: task.id,
            taskBranch,
            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
            gitAuthorEmail,
            gitAuthorName,
            sshKeyPath,
          });
          continue;
        }

        // ── Generate briefing ────────────────────────────────────────────────
        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
        const baseContext = generateBriefing({
          taskId: task.id,
          featureId,
          taskTitle: task.title,
          taskBranch,
          taskRepo: task.repo,
          taskRepoRoot,
          workspaceRoot: workspaceLocalPath,
          gitAuthorEmail,
          gitAuthorName,
          implementationModel,
          resultPath,
        });
        const briefingContent = ragPreFlight.block
          ? `${baseContext}\n\n${ragPreFlight.block}`
          : baseContext;

        // ── Write briefing via BriefingTransportPort ─────────────────────────
        // Use taskId as the briefing handle so the file path matches the
        // existing briefing-{taskId}/briefing.md convention.
        const briefingPath = await ports.briefing.put(task.id, briefingContent);

        // ── Submit executor (async — T6) ─────────────────────────────────────
        const execHandle = await buildAndSubmitExecutor({
          task, featureId, workspaceId: workspaceYaml.workspace_id,
          taskRepoUrl, taskBranch, taskRepoRoot, implementationModel,
          briefingPath, resultPath, workspaceLocalPath,
        });

        // Persist handle to task YAML for broker crash-recovery reconciliation.
        try {
          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
        } catch (e) {
          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
        }

        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
        if (runtimeProfile === "local-docker") dockerInFlight++;
        outcome = "ran_task";
        break outerLoop;
      }
    }

    // ── Fix-agent dispatch ────────────────────────────────────────────────────
    if (outcome !== "ran_task") {
      fixLoop:
      for (const watchUrl of config.watches) {
        if (haltedUrls.has(watchUrl)) continue;

        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
        if (!existsSync(workspaceLocalPath)) continue;

        let fixableTasks;
        try {
          fixableTasks = findFixableTasks(config, workspaceLocalPath);
        } catch (e) {
          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
          continue;
        }

        for (const { task, featureId } of fixableTasks) {
          const taskBranch = taskBranchName(featureId, task.id);
          const claimResult = await claimFixTask({
            workspaceRoot: workspaceLocalPath,
            taskId: task.id,
            featureId,
            gitAuthorEmail,
            gitAuthorName,
            jitterMaxSeconds: config.jitter_max_seconds,
          });

          if (!claimResult.won) {
            emit({ type: "fix_claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
            continue;
          }

          emit({ type: "fix_task_claimed", task_id: task.id, feature_id: featureId });

          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
          const fixWsYaml = parseYaml(
            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
          ) as { workspace_id: string };

          const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
          const prUrl = extractPrUrlFromTask(task);
          const fixContext = generateFixBriefing({
            taskId: task.id,
            featureId,
            taskTitle: task.title,
            taskBranch,
            taskRepo: task.repo,
            taskRepoRoot,
            workspaceRoot: workspaceLocalPath,
            prUrl: prUrl ?? "",
            gitAuthorEmail,
            gitAuthorName,
            implementationModel,
            resultPath,
          });

          emit({ type: "fix_briefing_generated", task_id: task.id, feature_id: featureId, pr_url: prUrl });
          const fixBriefingPath = await ports.briefing.put(task.id, fixContext);
          const fixHandle = await buildAndSubmitExecutor({
            task, featureId, workspaceId: fixWsYaml.workspace_id,
            taskRepoUrl, taskBranch, taskRepoRoot: taskRepoRoot, implementationModel,
            briefingPath: fixBriefingPath, resultPath, workspaceLocalPath,
          });
          emit({ type: "fix_executor_submitted", task_id: task.id, feature_id: featureId, handle: fixHandle });
          if (runtimeProfile === "local-docker") dockerInFlight++;
          outcome = "ran_task";
          break fixLoop;
        }
      }
    }

    // ── Reviewer dispatch ─────────────────────────────────────────────────────
    if (outcome !== "ran_task") {
      reviewerLoop:
      for (const watchUrl of config.watches) {
        if (haltedUrls.has(watchUrl)) continue;

        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
        if (!existsSync(workspaceLocalPath)) continue;

        let reviewableTasks;
        try {
          reviewableTasks = findReviewableTasks(config, workspaceLocalPath);
        } catch (e) {
          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
          continue;
        }

        for (const { task, featureId } of reviewableTasks) {
          const taskBranch = taskBranchName(featureId, task.id);
          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
          const wsModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
          const revWsYaml = parseYaml(
            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
          ) as { workspace_id: string };
          let reviewModelOverrides = {};
          try {
            const tMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
            reviewModelOverrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), task.id);
          } catch { /* non-fatal */ }
          const reviewerModel = resolveModel(wsModelPolicy, reviewModelOverrides, "self_review", task.id);

          const dispatchResult = await dispatchReviewer({
            workspaceRoot: workspaceLocalPath,
            featureId,
            taskId: task.id,
            taskBranch,
            implRepoRoot: taskRepoRoot,
            implRepoUrl: taskRepoUrl,
            gitAuthorEmail,
            gitAuthorName,
            workflowLocalPath,
            maxTurns: config.budget.max_iterations,
            maxTokens: config.budget.max_tokens_per_task,
            logSinkEnabled: config.log_sink.enabled,
            reviewerModel,
            workspaceId: revWsYaml.workspace_id,
            githubToken,
            broker: ports.broker,
            callbackUrl: ports.broker.getCallbackUrl() ?? "",
            emit,
