65	/**
66	 * Returns an invokeClaudeForResolution function that pins Claude to a specific model.
67	 * Passed to all conflict-resolution handlers so they respect workspace model_policy
68	 * instead of defaulting to whatever the Claude CLI ships with.
69	 */
70	function makeConflictResolver(
71	  model: string,
72	  maxTurns = 10,
73	): (prompt: string, cwd: string, env: NodeJS.ProcessEnv) => Promise<boolean> {
74	  return (prompt, cwd, env) =>
75	    new Promise((resolve) => {
76	      const child = spawn(
77	        "claude",
78	        [
79	          "-p", prompt,
80	          "--model", model,
81	          "--max-turns", String(maxTurns),
82	          "--output-format", "stream-json",
83	          "--verbose",
84	          "--dangerously-skip-permissions",
85	        ],
86	        { cwd, env, stdio: ["ignore", "pipe", "pipe"] },
87	      );
88	      child.stdout.pipe(process.stdout);
89	      child.stderr.pipe(process.stderr);
90	      child.on("close", (code) => resolve(code === 0));
91	      child.on("error", () => resolve(false));
92	    });
93	}
