106	/** Emit a structured JSON event via the profile's EventEmitterPort. */
107	function makeEmit(ports: RuntimePorts): (event: Record<string, unknown>) => void {
108	  return (event: Record<string, unknown>) => {
109	    const { type, ...data } = event as { type?: string } & Record<string, unknown>;
110	    ports.emitter.emit(type ?? "event", data);
111	  };
112	}
