114	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
115	  const task = parseYaml(
116	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
117	  ) as { repo: string };
118	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
119	  return task.repo;
