129	function resolveTaskContext(
130	  workspaceLocalPath: string,
131	  featureId: string,
132	  task: Task,
133	): TaskContext {
134	  const workspaceModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
135	  const taskRepoRoot = resolveRepoLocalPath(workspaceLocalPath, task.repo);
136	  const taskRepoUrl = resolveRepoGitUrl(workspaceLocalPath, task.repo);
137	  const taskBaseBranch = resolveRepoBaseBranch(workspaceLocalPath, task.repo);
138	
139	  const tasksMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
140	  let taskModelOverrides = {};
141	  try {
142	    taskModelOverrides = parseModelOverrides(readFileSync(tasksMdPath, "utf-8"), task.id);
143	  } catch { /* non-fatal */ }
144	
145	  const implementationModel = resolveModel(
146	    workspaceModelPolicy,
147	    taskModelOverrides,
148	    "implementation",
149	    task.id,
150	  );
151	
152	  return { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel };
153	}
