155	/**
156	 * Write a rag_pre_flight log entry to the task YAML before spawning the executor.
157	 * Commits and pushes to the task branch. Throws on error.
158	 */
159	function writeRagPreFlight(
160	  workspaceRoot: string,
161	  featureId: string,
162	  taskId: string,
163	  taskBranch: string,
164	  gitAuthorEmail: string,
165	  gitAuthorName: string,
166	  sshKeyPath: string | undefined,
167	  ragPreFlight: { query: string; injected: boolean; summary: string },
168	): void {
169	  const now = new Date().toISOString();
170	  const entry: TaskLogEntry = {
171	    action: "rag_pre_flight",
172	    by: gitAuthorEmail,
173	    at: now,
174	    rag_context_injected: ragPreFlight.injected,
175	    rag_summary: ragPreFlight.summary,
176	    rag_query: ragPreFlight.query,
177	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
178	  };
179	
180	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
181	  const relPath = taskYamlRelPath(featureId, taskId);
182	  const gitOpts = {
183	    cwd: workspaceRoot,
184	    encoding: "utf-8" as const,
185	    env: buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName }),
186	    timeout: 30_000,
187	    stdio: "pipe" as const,
188	  };
189	
190	  // Anchor to the task branch tip before reading/writing — same pattern as
191	  // append-log and mutate-task-yaml. Defensive: claimTask leaves the repo on
192	  // the task branch, but an explicit anchor makes this function self-contained.
193	  execSync(`git fetch origin "${taskBranch}"`, gitOpts);
194	  execSync(`git checkout -B "${taskBranch}" "origin/${taskBranch}"`, gitOpts);
195	
196	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
197	  task.log.push(entry);
198	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
199	
200	  execSync(`git add "${relPath}"`, gitOpts);
201	  execSync(
202	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
203	    gitOpts,
204	  );
205	  execSync(`git push origin "${taskBranch}"`, gitOpts);
206	}
