208	// ── Main ──────────────────────────────────────────────────────────────────────
209	
210	async function main(): Promise<number> {
211	  let agentYamlPath: string;
212	  let workflowLocalPath: string;
213	  let workspacesRoot: string;
214	  let gitAuthorEmail: string;
215	
216	  // Bootstrap-time emit — before the profile is ready, write directly to stdout.
217	  const bootstrapEmit = (event: Record<string, unknown>) => {
218	    console.log(JSON.stringify({ at: new Date().toISOString(), ...event }));
219	  };
220	
221	  try {
222	    agentYamlPath = requireEnv("AGENT_YAML_PATH");
223	    workflowLocalPath = requireEnv("WORKFLOW_LOCAL_PATH");
224	    workspacesRoot = requireEnv("WORKSPACES_ROOT");
225	    gitAuthorEmail = requireEnv("GIT_AUTHOR_EMAIL");
226	  } catch (e) {
227	    bootstrapEmit({ type: "fatal_missing_env", details: (e as Error).message });
228	    return 4;
229	  }
230	
231	  const gitAuthorName = process.env.GIT_AUTHOR_NAME ?? gitAuthorEmail;
232	
233	  const sshResolution = resolveSSHKey(process.env);
234	  const sshKeyPath = sshResolution.sshKeyPath;
235	
236	  // ── Create the runtime profile ────────────────────────────────────────────────
237	  // RUNTIME_PROFILE selects the adapter set. Switching profiles at startup is how
238	  // new infra is added without core changes.
239	  //   local-subprocess (default) — executor + in-process broker in one container
240	  //   local-docker               — docker run -d executor + shared Redis broker (M:N)
241	  const runtimeProfile = process.env.RUNTIME_PROFILE ?? "local-subprocess";
242	  const ports: RuntimePorts & { broker: { start(): Promise<number>; stop(): Promise<void>; getCallbackUrl(): string | null } } =
243	    runtimeProfile === "local-docker"
244	      ? createLocalDockerProfile({
245	          gitAuthorEmail,
246	          gitAuthorName,
247	          sshKeyPath,
248	          brokerUrl: process.env.BROKER_URL ?? "http://broker:7000",
249	        })
250	      : createLocalSubprocessProfile({
251	          gitAuthorEmail,
252	          gitAuthorName,
253	          sshKeyPath,
254	        });
255	
256	  // Start the broker receiver (no-op for HttpBrokerAdapter; binds HTTP port for InMemoryBrokerAdapter).
257	  const brokerPort = await ports.broker.start();
258	
259	  const emit = makeEmit(ports);
260	  emit({ type: "broker_started", port: brokerPort, callback_url: ports.broker.getCallbackUrl() });
261	
262	  if (sshResolution.warned) {
263	    emit({ type: "warn_no_ssh_key", note: "SSH_PRIVATE_KEY is not set — git operations over SSH will fail." });
264	  }
265	
266	  const bootstrapResult = await runBootstrap({
267	    agentYamlPath,
268	    workflowLocalPath,
269	    workflowUrl: process.env.WORKFLOW_URL,
270	    workspacesRoot,
271	    sshKeyPath,
272	  });
273	
274	  if (bootstrapResult.exitCode !== 0) return bootstrapResult.exitCode;
275	
276	  const config = bootstrapResult.config!;
277	  const githubToken = process.env.GITHUB_TOKEN ?? "";
278	  if (!githubToken) emit({ type: "warn_no_github_token" });
279	
280	  // ── Feature Branch Lifecycle Manager (T8) ────────────────────────────────────
281	  // Runs once at startup — creates or syncs feature/{featureId} on each watched
282	  // workspace before the main dispatch loop begins.
283	  for (const watchUrl of config.watches) {
284	    const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
285	    if (!existsSync(workspaceLocalPath)) continue;
286	    try {
287	      const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
288	      runFeatureBranchLifecycle({
289	        workspaceRoot: workspaceLocalPath,
290	        baseBranch: mgmtCoords.baseBranch,
291	        gitAuthorEmail,
292	        gitAuthorName,
293	        sshKeyPath,
294	        emit,
295	      });
296	    } catch (e) {
297	      emit({ type: "feature_branch_lifecycle_workspace_error", workspace: watchUrl, details: String(e) });
298	    }
299	  }
300	
301	  let lastPrPollAt: number | null = null;
302	  // Local counter for local-docker mode — tracks how many executor containers are
303	  // in-flight. Incremented on submit, decremented when the reap loop acks a completion.
304	  // TODO: replace with broker.registrySize() once the broker exposes that endpoint.
305	  let dockerInFlight = 0;
306	
307	  async function buildAndSubmitExecutor(opts: {
308	    task: Task;
309	    featureId: string;
310	    workspaceId: string;
311	    taskRepoUrl: string;
312	    taskBranch: string;
313	    taskRepoRoot: string;
314	    implementationModel: string;
315	    briefingPath: string;
316	    resultPath: string;
317	    workspaceLocalPath: string;
318	  }) {
319	    const { task, featureId, workspaceId, taskRepoUrl, taskBranch, taskRepoRoot,
320	            implementationModel, briefingPath, resultPath, workspaceLocalPath } = opts;
321	
322	    const nonce = randomUUID();
323	    const callbackUrl = ports.broker.getCallbackUrl() ?? "";
324	
325	    const execInput: ExecutorPortInput = {
326	      taskId: task.id,
327	      featureId,
328	      workspaceId,
329	      taskRepoUrl,
330	      taskRepoBranch: taskBranch,
331	      taskRepoPath: taskRepoRoot,
332	      briefingPath,
333	      resultPath,
334	      budgetTokens: config.budget.max_tokens_per_task,
335	      implementationModel,
336	      sshPrivateKey: process.env.SSH_PRIVATE_KEY ?? "",
337	      githubToken,
338	      callbackUrl,
339	      nonce,
340	    };
341	
342	    const extraEnv: Record<string, string> = {
343	      WORKSPACE_ROOT: workspaceLocalPath,
344	      TASK_BRANCH: taskBranch,
345	      GIT_AUTHOR_EMAIL: gitAuthorEmail,
346	      GIT_AUTHOR_NAME: gitAuthorName,
347	      WORKFLOW_LOCAL_PATH: workflowLocalPath,
348	      MAX_TURNS: String(config.budget.max_iterations),
349	      LOG_SINK_ENABLED: config.log_sink.enabled ? "1" : "0",
350	      ...(process.env.MCP_RAG_URL ? { MCP_RAG_URL: process.env.MCP_RAG_URL } : {}),
351	      ...(process.env.FIGMA_PERSONAL_ACCESS_TOKEN
352	        ? { FIGMA_PERSONAL_ACCESS_TOKEN: process.env.FIGMA_PERSONAL_ACCESS_TOKEN }
353	        : {}),
354	    };
355	
356	    const adapter =
357	      runtimeProfile === "local-docker"
358	        ? new (await import("./adapters/executor/docker-run.js")).DockerRunAdapter({
359	            broker: ports.broker,
360	            extraEnv,
361	          })
362	        : new SubProcessAdapter({
363	            broker: ports.broker,
364	            extraEnv,
365	          });
366	
367	    return adapter.submit(execInput);
368	  }
369	
370	  async function runOneCycle(): Promise<CycleOutcome> {
371	    // In local-subprocess mode all repos share the same container filesystem.
372	    // If an executor is running, skip impl repo pulls — syncRepo would switch
373	    // the shared working tree to the base branch and hard-reset it, destroying
374	    // any uncommitted work the executor has in flight.
375	    const execInFlight =
376	      runtimeProfile === "local-subprocess"
377	        ? (ports.broker as InMemoryBrokerAdapter).registrySize() > 0
378	        : false;
379	
380	    const pullResults = pullWorkspaces({
381	      watchUrls: config.watches,
382	      sshKeyPath,
383	      workspacesRoot,
384	      workflowUrl: process.env.WORKFLOW_URL,
385	      workflowLocalPath,
386	      skipImplRepoPull: execInFlight,
387	      emit,
388	    });
389	
390	    const haltedUrls = new Set(
391	      pullResults
392	        .filter((r) => r.outcome === "halt" || r.outcome === "warn")
393	        .map((r) => r.url),
394	    );
395	
396	    let outcome: CycleOutcome = "idle";
397	    const pulledWorkspaceRoots: string[] = [];
398	
399	    // ── Subprocess concurrency guard + task dispatch ──────────────────────────
400	    // In local-subprocess mode all repos share the same container filesystem.
401	    // Two concurrent subprocesses can race on git checkouts in the same repo.
402	    // Wrap the dispatch loop in a labeled block so we can break out of it
403	    // (skipping to PR poll + reap) when a subprocess is already in-flight.
404	    dispatchBlock: {
405	      const defaultMax = runtimeProfile === "local-subprocess" ? 1 : 4;
406	      const maxConcurrent = config.max_concurrent_executors ?? defaultMax;
407	
408	      if (runtimeProfile === "local-subprocess") {
409	        const inFlight = (ports.broker as InMemoryBrokerAdapter).registrySize();
410	        if (inFlight >= maxConcurrent) {
411	          emit({ type: "executor_pool_full", in_flight: inFlight, max: maxConcurrent });
412	          break dispatchBlock;
413	        }
414	      } else if (runtimeProfile === "local-docker") {
415	        if (dockerInFlight >= maxConcurrent) {
416	          emit({ type: "executor_pool_full", in_flight: dockerInFlight, max: maxConcurrent });
417	          break dispatchBlock;
418	        }
419	      }
420	
421	    outerLoop:
422	    for (const watchUrl of config.watches) {
423	      if (haltedUrls.has(watchUrl)) continue;
424	
425	      const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
426	      pulledWorkspaceRoots.push(workspaceLocalPath);
427	
428	      if (!existsSync(workspaceLocalPath)) {
429	        emit({ type: "workspace_not_found", workspace_url: watchUrl });
430	        continue;
431	      }
432	
433	      let eligibleTasks;
434	      try {
435	        eligibleTasks = findEligibleTasks(config, workspaceLocalPath, workflowLocalPath);
436	      } catch (e) {
437	        emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
438	        continue;
439	      }
440	
441	      if (eligibleTasks.length === 0) {
442	        emit({ type: "no_eligible_tasks", workspace_url: watchUrl });
443	        continue;
444	      }
445	
446	      for (const { task, featureId } of eligibleTasks) {
447	        const claimResult = await claimTask({
448	          workspaceRoot: workspaceLocalPath,
449	          taskId: task.id,
450	          featureId,
451	          gitAuthorEmail,
452	          gitAuthorName,
453	          sshKeyPath,
454	          jitterMaxSeconds: config.jitter_max_seconds,
455	        });
456	
457	        const taskBranch = taskBranchName(featureId, task.id);
458	
459	        if (!claimResult.won) {
460	          if (claimResult.reason !== "branch_blocked_recovery") {
461	            emit({ type: "claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
462	            continue;
463	          }
464	          emit({ type: "task_blocked_recovery_detected", task_id: task.id, feature_id: featureId });
465	        } else {
466	          emit({ type: "task_claimed", task_id: task.id, feature_id: featureId });
467	        }
468	
469	        // ── Open management-repo PR ───────────────────────────────────────────
470	        if (githubToken) {
471	          try {
472	            const mgmtCoords = parseManagementRepoCoords(workspaceLocalPath);
473	            await openWorkspacePr({
474	              workspaceRoot: workspaceLocalPath,
475	              featureId,
476	              taskId: task.id,
477	              branch: taskBranch,
478	              // Task PRs target the feature branch so all task changes collect
479	              // there before the Handoff Trigger merges to the base branch (T8).
480	              baseBranch: featureBranchName(featureId),
481	              githubToken,
482	              repoOwner: mgmtCoords.owner,
483	              repoName: mgmtCoords.repo,
484	              gitAuthorEmail,
485	              gitAuthorName,
486	              sshKeyPath,
487	            });
488	            emit({ type: "workspace_pr_opened", task_id: task.id, feature_id: featureId });
489	          } catch (e) {
490	            const stderr = (e as { stderr?: Buffer | string }).stderr;
491	            const stderrStr = stderr instanceof Buffer ? stderr.toString("utf-8") : (stderr ?? "");
492	            emit({ type: "workspace_pr_failed", task_id: task.id, feature_id: featureId, details: String(e), stderr: stderrStr });
493	          }
494	        }
495	
496	        // ── Resolve model + task repo ────────────────────────────────────────
497	        const { taskRepoRoot, taskRepoUrl, taskBaseBranch, implementationModel } =
498	          resolveTaskContext(workspaceLocalPath, featureId, task);
499	
500	        // ── RAG pre-flight ───────────────────────────────────────────────────
501	        const mcpRagUrl = process.env.MCP_RAG_URL;
502	        const workspaceYaml = parseYaml(
503	          readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
504	        ) as { workspace_id: string };
505	        const ragQuery = `${task.title} ${featureId}`;
506	        const ragPreFlight = await fetchRagContext(mcpRagUrl, ragQuery, workspaceYaml.workspace_id);
507	
508	        try {
509	          writeRagPreFlight(
510	            workspaceLocalPath,
511	            featureId,
512	            task.id,
513	            taskBranch,
514	            gitAuthorEmail,
515	            gitAuthorName,
516	            sshKeyPath,
517	            { query: ragQuery, injected: ragPreFlight.injected, summary: ragPreFlight.summary },
518	          );
519	        } catch (e) {
520	          const details = String(e);
521	          emit({ type: "rag_pre_flight_failed", task_id: task.id, feature_id: featureId, details });
522	          mutateTaskYaml({
523	            workspaceRoot: workspaceLocalPath,
524	            featureId,
525	            taskId: task.id,
526	            taskBranch,
527	            result: { terminal_status: "failed", blocked_reason: `rag_pre_flight_error: ${details}` },
528	            gitAuthorEmail,
529	            gitAuthorName,
530	            sshKeyPath,
531	          });
532	          continue;
533	        }
534	
535	        // ── Generate briefing ────────────────────────────────────────────────
536	        const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
537	        const baseContext = generateBriefing({
538	          taskId: task.id,
539	          featureId,
540	          taskTitle: task.title,
541	          taskBranch,
542	          taskRepo: task.repo,
543	          taskRepoRoot,
544	          workspaceRoot: workspaceLocalPath,
545	          gitAuthorEmail,
546	          gitAuthorName,
547	          implementationModel,
548	          resultPath,
549	        });
550	        const briefingContent = ragPreFlight.block
551	          ? `${baseContext}\n\n${ragPreFlight.block}`
552	          : baseContext;
553	
554	        // ── Write briefing via BriefingTransportPort ─────────────────────────
555	        // Use taskId as the briefing handle so the file path matches the
556	        // existing briefing-{taskId}/briefing.md convention.
557	        const briefingPath = await ports.briefing.put(task.id, briefingContent);
558	
559	        // ── Submit executor (async — T6) ─────────────────────────────────────
560	        const execHandle = await buildAndSubmitExecutor({
561	          task, featureId, workspaceId: workspaceYaml.workspace_id,
562	          taskRepoUrl, taskBranch, taskRepoRoot, implementationModel,
563	          briefingPath, resultPath, workspaceLocalPath,
564	        });
565	
566	        // Persist handle to task YAML for broker crash-recovery reconciliation.
567	        try {
568	          await ports.workflowState.persistHandle(workspaceLocalPath, featureId, task.id, execHandle);
569	        } catch (e) {
570	          emit({ type: "persist_handle_failed", task_id: task.id, feature_id: featureId, details: String(e) });
571	        }
572	
573	        emit({ type: "executor_submitted", task_id: task.id, feature_id: featureId, handle: execHandle });
574	        if (runtimeProfile === "local-docker") dockerInFlight++;
575	        outcome = "ran_task";
576	        break outerLoop;
577	      }
578	    }
579	
580	    // ── Fix-agent dispatch ────────────────────────────────────────────────────
581	    if (outcome !== "ran_task") {
582	      fixLoop:
583	      for (const watchUrl of config.watches) {
584	        if (haltedUrls.has(watchUrl)) continue;
585	
586	        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
587	        if (!existsSync(workspaceLocalPath)) continue;
588	
589	        let fixableTasks;
590	        try {
591	          fixableTasks = findFixableTasks(config, workspaceLocalPath);
592	        } catch (e) {
593	          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
594	          continue;
595	        }
596	
597	        for (const { task, featureId } of fixableTasks) {
598	          const taskBranch = taskBranchName(featureId, task.id);
599	          const claimResult = await claimFixTask({
600	            workspaceRoot: workspaceLocalPath,
601	            taskId: task.id,
602	            featureId,
603	            gitAuthorEmail,
604	            gitAuthorName,
605	            jitterMaxSeconds: config.jitter_max_seconds,
606	          });
607	
608	          if (!claimResult.won) {
609	            emit({ type: "fix_claim_lost", task_id: task.id, feature_id: featureId, reason: claimResult.reason });
610	            continue;
611	          }
612	
613	          emit({ type: "fix_task_claimed", task_id: task.id, feature_id: featureId });
614	
615	          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
616	          const fixWsYaml = parseYaml(
617	            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
618	          ) as { workspace_id: string };
619	
620	          const resultPath = join(tmpdir(), `executor-result-${task.id}.json`);
621	          const prUrl = extractPrUrlFromTask(task);
622	          const fixContext = generateFixBriefing({
623	            taskId: task.id,
624	            featureId,
625	            taskTitle: task.title,
626	            taskBranch,
627	            taskRepo: task.repo,
628	            taskRepoRoot,
629	            workspaceRoot: workspaceLocalPath,
630	            prUrl: prUrl ?? "",
631	            gitAuthorEmail,
632	            gitAuthorName,
633	            implementationModel,
634	            resultPath,
635	          });
636	
637	          emit({ type: "fix_briefing_generated", task_id: task.id, feature_id: featureId, pr_url: prUrl });
638	          const fixBriefingPath = await ports.briefing.put(task.id, fixContext);
639	          const fixHandle = await buildAndSubmitExecutor({
640	            task, featureId, workspaceId: fixWsYaml.workspace_id,
641	            taskRepoUrl, taskBranch, taskRepoRoot: taskRepoRoot, implementationModel,
642	            briefingPath: fixBriefingPath, resultPath, workspaceLocalPath,
643	          });
644	          emit({ type: "fix_executor_submitted", task_id: task.id, feature_id: featureId, handle: fixHandle });
645	          if (runtimeProfile === "local-docker") dockerInFlight++;
646	          outcome = "ran_task";
647	          break fixLoop;
648	        }
649	      }
650	    }
651	
652	    // ── Reviewer dispatch ─────────────────────────────────────────────────────
653	    if (outcome !== "ran_task") {
654	      reviewerLoop:
655	      for (const watchUrl of config.watches) {
656	        if (haltedUrls.has(watchUrl)) continue;
657	
658	        const workspaceLocalPath = join(workspacesRoot, extractRepoName(watchUrl));
659	        if (!existsSync(workspaceLocalPath)) continue;
660	
661	        let reviewableTasks;
662	        try {
663	          reviewableTasks = findReviewableTasks(config, workspaceLocalPath);
664	        } catch (e) {
665	          emit({ type: "eligibility_error", workspace_url: watchUrl, details: String(e) });
666	          continue;
667	        }
668	
669	        for (const { task, featureId } of reviewableTasks) {
670	          const taskBranch = taskBranchName(featureId, task.id);
671	          const { taskRepoRoot, taskRepoUrl, implementationModel } = resolveTaskContext(workspaceLocalPath, featureId, task);
672	          const wsModelPolicy = loadWorkspaceModelPolicy(workspaceLocalPath);
673	          const revWsYaml = parseYaml(
674	            readFileSync(workspaceYamlPath(workspaceLocalPath), "utf-8"),
675	          ) as { workspace_id: string };
676	          let reviewModelOverrides = {};
677	          try {
678	            const tMdPath = join(workspaceLocalPath, "docs", "features", featureId, "tasks.md");
679	            reviewModelOverrides = parseModelOverrides(readFileSync(tMdPath, "utf-8"), task.id);
680	          } catch { /* non-fatal */ }
681	          const reviewerModel = resolveModel(wsModelPolicy, reviewModelOverrides, "self_review", task.id);
682	
683	          const dispatchResult = await dispatchReviewer({
684	            workspaceRoot: workspaceLocalPath,
685	            featureId,
686	            taskId: task.id,
687	            taskBranch,
688	            implRepoRoot: taskRepoRoot,
689	            implRepoUrl: taskRepoUrl,
690	            gitAuthorEmail,
691	            gitAuthorName,
692	            workflowLocalPath,
693	            maxTurns: config.budget.max_iterations,
694	            maxTokens: config.budget.max_tokens_per_task,
695	            logSinkEnabled: config.log_sink.enabled,
696	            reviewerModel,
697	            workspaceId: revWsYaml.workspace_id,
698	            githubToken,
699	            broker: ports.broker,
700	            callbackUrl: ports.broker.getCallbackUrl() ?? "",
701	            emit,
702	          });
703	
704	          if (dispatchResult === "dispatched") {
705	            if (runtimeProfile === "local-docker") dockerInFlight++;
706	            outcome = "ran_task";
707	            break reviewerLoop;
708	          }
709	        }
710	      }
711	    }
712	    } // end dispatchBlock
713	
714	    // ── In-review PR poll ─────────────────────────────────────────────────────
715	    // In local-subprocess mode the executor subprocess shares the same container
716	    // filesystem as the orchestrator. Both can race on `git rebase` in the same
717	    // repo — a second rebase operation fails with "rebase-merge directory already
718	    // exists". Re-check in-flight count here (not just in dispatchBlock) because
719	    // pulledWorkspaceRoots is already populated on the same cycle that dispatched
720	    // the executor; the dispatchBlock early-break only fires on *subsequent* cycles.
721	    const skipPrPoll =
722	      runtimeProfile === "local-subprocess" &&
723	      (ports.broker as InMemoryBrokerAdapter).registrySize() > 0;
724	    if (githubToken && !skipPrPoll) {
725	      const prPollIntervalMs =
726	        (config.pr_poll_interval_seconds ?? config.idle_sleep_seconds ?? 60) * 1000;
727	      const now = Date.now();
728	
729	      if (lastPrPollAt === null || now - lastPrPollAt >= prPollIntervalMs) {
730	        if (pulledWorkspaceRoots.length > 0) lastPrPollAt = now;
731	        try {
732	          const { prResults, workspacePrRecoveries } = await checkInReviewPrs({
733	            workspaceRoots: pulledWorkspaceRoots,
734	            githubToken,
735	            emit,
736	          });
737	
738	          for (const wsRoot of pulledWorkspaceRoots) {
739	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
740	            if (wsResults.some((r) => r.mergeable === false)) {
741	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
742	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
743	              await handleMergeConflicts({
744	                prResults: wsResults,
745	                workspaceRoot: wsRoot,
746	                resolveImplRepoRoot: (repoId) => resolveRepoLocalPath(wsRoot, repoId),
747	                resolveImplBaseBranch: (repoId) => resolveRepoBaseBranch(wsRoot, repoId),
748	                resolveTaskRepoId: (fId, tId) => resolveTaskRepoId(wsRoot, fId, tId),
749	                gitAuthorEmail,
750	                gitAuthorName,
751	                sshKeyPath,
752	                emit,
753	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
754	              });
755	            }
756	          }
757	
758	          for (const wsRoot of pulledWorkspaceRoots) {
759	            const wsResults = prResults.filter((r) => r.workspaceRoot === wsRoot);
760	            if (wsResults.some((r) => r.merged === true)) {
761	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
762	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
763	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
764	              await handleMergedPrs({
765	                prResults: wsResults,
766	                workspaceRoot: wsRoot,
767	                mgmtRepoOwner: mgmtCoords.owner,
768	                mgmtRepoName: mgmtCoords.repo,
769	                mgmtBaseBranch: mgmtCoords.baseBranch,
770	                githubToken,
771	                gitAuthorEmail,
772	                gitAuthorName,
773	                sshKeyPath,
774	                emit,
775	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
776	              });
777	            }
778	          }
779	
780	          for (const wsRoot of pulledWorkspaceRoots) {
781	            const wsRecoveries = workspacePrRecoveries.filter((r) => r.workspaceRoot === wsRoot);
782	            if (wsRecoveries.length > 0) {
783	              const wsModelPolicy = loadWorkspaceModelPolicy(wsRoot);
784	              const conflictModel = resolveModel(wsModelPolicy, {}, "conflict_resolution", "conflict-resolver");
785	              const mgmtCoords = parseManagementRepoCoords(wsRoot);
786	              await handleWorkspacePrRecoveries({
787	                recoveries: wsRecoveries,
788	                mgmtRepoOwner: mgmtCoords.owner,
789	                mgmtRepoName: mgmtCoords.repo,
790	                mgmtBaseBranch: mgmtCoords.baseBranch,
791	                githubToken,
792	                gitAuthorEmail,
793	                gitAuthorName,
794	                sshKeyPath,
795	                emit,
796	                invokeClaudeForResolution: makeConflictResolver(conflictModel),
797	              });
798	            }
799	          }
800	        } catch (e) {
801	          emit({ type: "in_review_poll_error", details: String(e) });
802	        }
803	      }
804	    }
805	
806	    // ── Shared reap loop ──────────────────────────────────────────────────────
807	    // Drain completions posted by in-flight executors this cycle (and any
808	    // leftovers from previous cycles). Routes by handle.kind → dispatcher.
809	    try {
810	      const reapResult = await runReapLoop({
811	        broker: ports.broker,
812	        workspaceRoots: pulledWorkspaceRoots,
813	        gitAuthorEmail,
814	        gitAuthorName,
815	        sshKeyPath,
816	        githubToken,
817	        emit,
818	      });
819	      if (reapResult.dispatched > 0) {
820	        if (runtimeProfile === "local-docker") {
821	          dockerInFlight = Math.max(0, dockerInFlight - reapResult.dispatched);
822	        }
823	        emit({ type: "reap_cycle_complete", dispatched: reapResult.dispatched, failed: reapResult.failed });
824	        if (outcome === "idle") outcome = "ran_task";
825	      }
826	    } catch (e) {
827	      emit({ type: "reap_loop_error", details: String(e) });
828	    }
829	
830	    return outcome;
831	  }
832	
833	  await runAgentLoop({ config, runCycle: runOneCycle, emit, scheduler: ports.scheduler });
834	  return 0;
835	}
836	
837	main()
838	  .then((code) => process.exit(code))
839	  .catch((e) => {
840	    try {
841	      console.log(JSON.stringify({
842	        type: "fatal_error",
843	        details: (e as Error).message ?? String(e),
844	        at: new Date().toISOString(),
845	      }));
846	    } catch { /* last resort */ }
847	    process.exit(4);
848	  });
849

