/**
 * State invariant checker — recovery mechanism for missed transitions.
 *
 * Called at most once every STATE_INVARIANT_CHECK_INTERVAL cycles inside the
 * existing poll loop, after handleMergedPrs. Not a new timer or process.
 *
 * Checks two invariant violations per feature:
 *
 *   1. Stuck dependent — a todo task whose entire depends_on list is done
 *      was not transitioned to ready (missed auto-ready cascade).
 *
 *   2. Stuck handoff — all tasks are done/cancelled (at least one done),
 *      feature_status is not "in_handoff", and handoff_pr_url is null
 *      (missed handoff trigger).
 *
 * Each violation is processed independently; one failure does not block others.
 * Emits state_invariant_violation for each correction applied.
 */

import { existsSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { execSync, spawnSync } from "node:child_process";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import type { Task } from "../types/task.js";
import {
  featuresRoot,
  statusYamlAbsPath,
  taskBranchName,
  taskYamlAbsPath,
  taskYamlRelPath,
  TASKS_DIR,
} from "../paths.js";
import { buildGitEnv } from "../git-env.js";
import { fireHandoffTrigger } from "../handoff/handoff-trigger.js";
import { parseManagementRepoCoords } from "../config/workspace-config.js";

// ── Types ─────────────────────────────────────────────────────────────────────

export interface RunStateInvariantCheckOpts {
  workspaceRoot: string;
  githubToken: string;
  gitAuthorEmail: string;
  gitAuthorName?: string;
  sshKeyPath?: string;
  emit: (event: Record<string, unknown>) => void;
}

interface StatusYaml {
  feature_status?: string;
  handoff_pr_url?: string | null;
  [key: string]: unknown;
}

// ── Helpers ───────────────────────────────────────────────────────────────────

function listFeatureIds(workspaceRoot: string): string[] {
  const docsPath = featuresRoot(workspaceRoot);
  if (!existsSync(docsPath)) return [];
  try {
    return readdirSync(docsPath, { withFileTypes: true })
      .filter((e) => e.isDirectory())
      .map((e) => e.name);
  } catch {
    return [];
  }
}

function readTasksForFeature(workspaceRoot: string, featureId: string): Task[] {
  const tasksDir = join(featuresRoot(workspaceRoot), featureId, TASKS_DIR);
  let files: string[] = [];
  try {
    files = readdirSync(tasksDir).filter((f) => /^T\d+\.yaml$/.test(f));
  } catch {
    return [];
  }
  const tasks: Task[] = [];
  for (const file of files) {
    try {
      tasks.push(parseYaml(readFileSync(join(tasksDir, file), "utf-8")) as Task);
    } catch { /* skip unreadable */ }
  }
  return tasks;
}

function readStatusYaml(workspaceRoot: string, featureId: string): StatusYaml {
  const statusPath = statusYamlAbsPath(workspaceRoot, featureId);
  if (!existsSync(statusPath)) return {};
  try {
    return parseYaml(readFileSync(statusPath, "utf-8")) as StatusYaml;
  } catch {
    return {};
  }
}

// ── Stuck-dependent correction ────────────────────────────────────────────────

/**
 * For each done task, check siblings that are todo with all deps satisfied.
 * Transition those siblings to ready, append a log entry, write YAML,
 * commit, and push.
 */
async function fixStuckDependents(
  workspaceRoot: string,
  featureId: string,
  tasks: Task[],
  gitAuthorEmail: string,
  gitAuthorName: string,
  sshKeyPath: string | undefined,
  emit: (event: Record<string, unknown>) => void,
): Promise<void> {
  const doneTasks = tasks.filter((t) => t.status === "done" || t.status === "cancelled");
  if (doneTasks.length === 0) return;

  const statusMap = new Map(tasks.map((t) => [t.id, t.status]));

  for (const task of tasks) {
    if (task.status !== "todo") continue;
    if (!Array.isArray(task.depends_on) || task.depends_on.length === 0) continue;

    const allDepsDone = task.depends_on.every(
      (depId) => statusMap.get(depId) === "done" || statusMap.get(depId) === "cancelled",
    );
    if (!allDepsDone) continue;

    // This is a stuck dependent — apply the ready transition.
    emit({
      type: "state_invariant_violation",
      kind: "stuck_dependent",
      feature_id: featureId,
      task_id: task.id,
      note: `Task ${task.id} todo with all deps done — applying ready transition`,
    });

    const env = buildGitEnv(sshKeyPath, { email: gitAuthorEmail, name: gitAuthorName });
    const taskBranch = taskBranchName(featureId, task.id);
    const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, task.id);
    const relPath = taskYamlRelPath(featureId, task.id);

    try {
      execSync(`git -C "${workspaceRoot}" fetch origin`, { env, stdio: "pipe" });

      // Check whether the branch exists on origin; if not, skip — we can't
      // safely write to a task that has no branch on origin.
      try {
        execSync(
          `git -C "${workspaceRoot}" ls-remote --exit-code --heads origin "${taskBranch}"`,
          { env, stdio: "pipe" },
        );
      } catch {
        emit({
          type: "state_invariant_correction_skipped",
          kind: "stuck_dependent",
          feature_id: featureId,
          task_id: task.id,
          reason: "task_branch_not_on_origin",
        });
        continue;
      }

      execSync(`git -C "${workspaceRoot}" checkout "${taskBranch}"`, { env, stdio: "pipe" });
      execSync(
        `git -C "${workspaceRoot}" reset --hard "origin/${taskBranch}"`,
        { env, stdio: "pipe" },
      );

      const liveTask = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
      if (liveTask.status !== "todo") continue; // already moved — skip

      const now = new Date().toISOString();
      liveTask.status = "ready";
      liveTask.log.push({
        action: "ready",
        by: gitAuthorEmail,
        at: now,
        note: "State invariant checker: all deps done, task was stuck in todo.",
      });
      writeFileSync(yamlPath, yamlStringify(liveTask), "utf-8");

      execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
      execSync(
        `git -C "${workspaceRoot}" commit -m "chore(${task.id}): invariant-checker → ready"`,
        { env, stdio: "pipe" },
      );

      const push = spawnSync("git", ["-C", workspaceRoot, "push", "origin", taskBranch], {
        env,
        encoding: "utf-8",
      });

      if (push.status !== 0) {
        emit({
          type: "state_invariant_correction_failed",
          kind: "stuck_dependent",
          feature_id: featureId,
          task_id: task.id,
          details: push.stderr ?? "",
        });
      } else {
        emit({
          type: "state_invariant_corrected",
          kind: "stuck_dependent",
          feature_id: featureId,
          task_id: task.id,
        });
      }
    } catch (e) {
      emit({
        type: "state_invariant_correction_failed",
        kind: "stuck_dependent",
        feature_id: featureId,
        task_id: task.id,
        details: String(e),
      });
    }
  }
}

// ── Stuck-handoff correction ──────────────────────────────────────────────────

/**
 * If all tasks are done/cancelled (at least one done), feature_status is not
 * "in_handoff", and handoff_pr_url is null, re-invoke fireHandoffTrigger.
 */
async function fixStuckHandoff(
  workspaceRoot: string,
  featureId: string,
  tasks: Task[],
  statusYaml: StatusYaml,
  githubToken: string,
  gitAuthorEmail: string,
  gitAuthorName: string,
  sshKeyPath: string | undefined,
  emit: (event: Record<string, unknown>) => void,
): Promise<void> {
  if (tasks.length === 0) return;

  const hasDone = tasks.some((t) => t.status === "done");
  const allTerminal = tasks.every(
    (t) => t.status === "done" || t.status === "cancelled",
  );

  if (!hasDone || !allTerminal) return;
  if (statusYaml.feature_status === "in_handoff") return;
  if (statusYaml.handoff_pr_url) return;

  emit({
    type: "state_invariant_violation",
    kind: "stuck_handoff",
    feature_id: featureId,
    note: "All tasks done but handoff not triggered — re-invoking fireHandoffTrigger",
  });

  if (!githubToken) {
    emit({
      type: "state_invariant_correction_skipped",
      kind: "stuck_handoff",
      feature_id: featureId,
      reason: "no_github_token",
    });
    return;
  }

  try {
    const { owner, repo, baseBranch } = parseManagementRepoCoords(workspaceRoot);
    const result = await fireHandoffTrigger({
      workspaceRoot,
      featureId,
      baseBranch,
      githubToken,
      repoOwner: owner,
      repoName: repo,
      gitAuthorEmail,
      gitAuthorName,
      sshKeyPath,
      emit,
    });

    if (result.error) {
      emit({
        type: "state_invariant_correction_failed",
        kind: "stuck_handoff",
        feature_id: featureId,
        details: result.error,
      });
    } else {
      emit({
        type: "state_invariant_corrected",
        kind: "stuck_handoff",
        feature_id: featureId,
        pr_url: result.prUrl,
      });
    }
  } catch (e) {
    emit({
      type: "state_invariant_correction_failed",
      kind: "stuck_handoff",
      feature_id: featureId,
      details: String(e),
    });
  }
}

// ── Public API ────────────────────────────────────────────────────────────────

/**
 * Scan all features in the workspace for state invariant violations.
 * Non-throwing: each feature and each violation is processed independently.
 */
export async function runStateInvariantCheck(
  opts: RunStateInvariantCheckOpts,
): Promise<void> {
  const {
    workspaceRoot,
    githubToken,
    gitAuthorEmail,
    gitAuthorName = gitAuthorEmail,
    sshKeyPath,
    emit,
  } = opts;

  const featureIds = listFeatureIds(workspaceRoot);

  for (const featureId of featureIds) {
    try {
      const tasks = readTasksForFeature(workspaceRoot, featureId);
      if (tasks.length === 0) continue;

      const statusYaml = readStatusYaml(workspaceRoot, featureId);

      await fixStuckDependents(
        workspaceRoot,
        featureId,
        tasks,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        emit,
      );

      await fixStuckHandoff(
        workspaceRoot,
        featureId,
        tasks,
        statusYaml,
        githubToken,
        gitAuthorEmail,
        gitAuthorName,
        sshKeyPath,
        emit,
      );
    } catch (e) {
      emit({
        type: "state_invariant_check_error",
        feature_id: featureId,
        details: String(e),
      });
    }
  }
}

