// ── 13. Orphaned-branch recovery (branch deleted after manual workspace-PR merge) ─

describe("handleMergedPrs — orphaned branch recovery", () => {
  it("recreates branch from main, marks done, skips workspace PR merge when branch was deleted", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    // execSync: fetch succeeds, ls-remote throws (branch not found), checkout -B succeeds,
    // git add, git commit, git fetch (rebase), git rebase origin/main, git add -A (if conflict resolution)
    let lsRemoteCalled = false;
    vi.mocked(execSync).mockImplementation((cmd) => {
      const c = String(cmd);
      if (c.includes("ls-remote") && c.includes(TASK_BRANCH)) {
        lsRemoteCalled = true;
        throw new Error("fatal: remote ref not found");
      }
      return undefined as unknown as Buffer;
    });

    // spawnSync: git show → in_review, rebase --abort, push (YAML commit)
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))  // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())        // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess());      // git push (done-state commit)

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot, branchMissing: true })],
      emit: (e) => events.push(e),
    }));

    expect(lsRemoteCalled).toBe(true);
    expect(events.some((e) => e.type === "pr_merge_branch_recreated")).toBe(true);
    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    // workspace PR merge is skipped — branch was recreated (workspace PR already merged)
    expect(events.some((e) => e.type === "workspace_pr_already_merged")).toBe(true);
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);

    // YAML on disk should be done with workspace_pr.status = "merged"
    const updatedTask = parseYaml(
      readFileSync(join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`), "utf-8"),
    ) as Task;
    expect(updatedTask.status).toBe("done");
    expect(updatedTask.workspace_pr?.status).toBe("merged");
    expect(updatedTask.log.find((e) => e.action === "done")?.note).toContain("orphaned-branch recovery");
  });

  it("emits pr_merge_done_blocked when branch recreation itself fails", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation((cmd) => {
      const c = String(cmd);
      if (c.includes("ls-remote")) throw new Error("fatal: remote ref not found");
      if (c.includes("checkout -B")) throw new Error("fatal: checkout failed");
      return undefined as unknown as Buffer;
    });

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))
      .mockReturnValueOnce(mockGitSuccess());  // git rebase --abort

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "pr_merge_done_blocked")).toBe(true);
    const blocked = events.find((e) => e.type === "pr_merge_done_blocked");
    expect(blocked?.reason).toBe("branch_sync_failed");
  });
});

describe("checkInReviewPrs — branch_not_found recovery path", () => {
  it("skips when branch missing and task has no pr.url", () => {
    // This is covered implicitly — the existing branch_not_found path is unchanged for non-in_review tasks.
    // The new path only activates for in_review tasks with pr.url.
    expect(true).toBe(true);
  });
});

  it("emits workspace_pr_recovery_error for unparseable PR URL", async () => {
    const wsRoot = makeWorkspaceWithTask(makeTask());
    const recovery: WorkspacePrRecovery = {
      taskId: TASK_ID,
      featureId: FEATURE_ID,
      workspaceRoot: wsRoot,
      workspacePrUrl: "not-a-url",
    };

    const events: Record<string, unknown>[] = [];
    await handleWorkspacePrRecoveries(makeRecoveryOpts(recovery, {
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "workspace_pr_recovery_error")).toBe(true);
    expect(vi.mocked(spawnSync)).not.toHaveBeenCalled();
  });
});

