      .mockReturnValueOnce(mockGitShowTask(task))  // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())        // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushRejected())      // first push rejected
      .mockReturnValueOnce({                        // git rebase origin/<taskBranch> (clean)
        pid: 0, output: [], stdout: "", stderr: "", status: 0, signal: null, error: undefined,
      } as unknown as ReturnType<typeof spawnSync>)
      .mockReturnValueOnce(mockPushRejected());     // retry push also rejected

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "pr_merge_done_blocked")).toBe(true);
    const blockedEvent = events.find((e) => e.type === "pr_merge_done_blocked");
    expect(blockedEvent?.reason).toBe("push_rejected_after_clean_rebase");
  });

  it("succeeds when push is rejected but rebase + retry push succeeds", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))  // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())        // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushRejected())      // first push rejected
      .mockReturnValueOnce(mockGitSuccess())        // git rebase origin/<taskBranch> (rejection recovery)
      .mockReturnValueOnce(mockPushSuccess())       // retry push succeeds
      .mockReturnValueOnce(mockGitSuccess())        // git rebase origin/main (before merge)
      .mockReturnValueOnce(mockPushSuccess())       // git push --force-with-lease (after rebase)
      .mockReturnValueOnce(mockCurlMergeSuccess()); // workspace PR merge

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    expect(events.some((e) => e.type === "workspace_pr_merged")).toBe(true);
  });
});

