describe("handleMergedPrs — handoff trigger when last task done via pr-merge loop", () => {
  it("fires handoff trigger when the merged task is the only (last) task in the feature", async () => {
    const task = makeTask({ workspace_pr: null });
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation(() => undefined as unknown as Buffer);
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))  // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())        // git rebase --abort
      .mockReturnValueOnce(mockPushSuccess());      // git push (done-state commit)

    vi.mocked(fireHandoffTrigger).mockResolvedValue({ prUrl: "https://github.com/org/repo/pull/99" });

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    expect(events.some((e) => e.type === "all_tasks_done")).toBe(true);
    expect(vi.mocked(fireHandoffTrigger)).toHaveBeenCalledOnce();
    expect(vi.mocked(fireHandoffTrigger)).toHaveBeenCalledWith(
      expect.objectContaining({
        workspaceRoot: wsRoot,
        featureId: FEATURE_ID,
        githubToken: GITHUB_TOKEN,
        repoOwner: MGMT_OWNER,
        repoName: MGMT_REPO,
      }),
    );
  });

  it("does not fire handoff trigger when a sibling task is still in progress", async () => {
    const task = makeTask({ workspace_pr: null });
    const siblingTask = makeTask({ id: "T2", status: "in_progress" as Task["status"] });
    const wsRoot = mkdtempSync(join(tmpdir(), "handle-merged-handoff-"));
    tmpDirs.push(wsRoot);
    const tasksDir = join(wsRoot, "docs", "features", FEATURE_ID, "tasks");
    mkdirSync(tasksDir, { recursive: true });
    writeFileSync(join(tasksDir, `${task.id}.yaml`), yamlStringify(task), "utf-8");
    writeFileSync(join(tasksDir, `${siblingTask.id}.yaml`), yamlStringify(siblingTask), "utf-8");

    vi.mocked(execSync).mockImplementation(() => undefined as unknown as Buffer);
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))  // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())        // git rebase --abort
      .mockReturnValueOnce(mockPushSuccess());      // git push (done-state commit)

    vi.mocked(fireHandoffTrigger).mockResolvedValue({ prUrl: "https://github.com/org/repo/pull/99" });

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    expect(events.some((e) => e.type === "all_tasks_done")).toBe(false);
    expect(vi.mocked(fireHandoffTrigger)).not.toHaveBeenCalled();
  });

  it("emits handoff_trigger_skipped when githubToken is absent", async () => {
    const task = makeTask({ workspace_pr: null });
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation(() => undefined as unknown as Buffer);
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))
      .mockReturnValueOnce(mockGitSuccess())
      .mockReturnValueOnce(mockPushSuccess());

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      githubToken: "",
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
    expect(events.some((e) => e.type === "handoff_trigger_skipped")).toBe(true);
    expect(vi.mocked(fireHandoffTrigger)).not.toHaveBeenCalled();
  });

  it("emits handoff_trigger_failed when fireHandoffTrigger returns an error", async () => {
    const task = makeTask({ workspace_pr: null });
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation(() => undefined as unknown as Buffer);
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))
      .mockReturnValueOnce(mockGitSuccess())
      .mockReturnValueOnce(mockPushSuccess());

    vi.mocked(fireHandoffTrigger).mockResolvedValue({ error: "Failed to open PR" });

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot })],
      emit: (e) => events.push(e),
    }));

    expect(events.some((e) => e.type === "all_tasks_done")).toBe(true);
    expect(events.some((e) => e.type === "handoff_trigger_failed")).toBe(true);
  });
});

