describe("handleMergedPrs — orphaned branch recovery", () => {
  it("recreates branch from main, marks done, skips workspace PR merge when branch was deleted", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    // execSync: fetch succeeds, ls-remote throws (branch not found), checkout -B succeeds,
    // git add, git commit, git fetch (rebase), git rebase origin/main, git add -A (if conflict resolution)
    let lsRemoteCalled = false;
    vi.mocked(execSync).mockImplementation((cmd) => {
      const c = String(cmd);
      if (c.includes("ls-remote") && c.includes(TASK_BRANCH)) {
        lsRemoteCalled = true;
        throw new Error("fatal: remote ref not found");
      }
      return undefined as unknown as Buffer;
    });

    // spawnSync: git show → in_review, rebase --abort, push (YAML commit)
    vi.mocked(spawnSync)
      .mockReturnValueOnce(mockGitShowTask(task))  // tryReadTaskFromBranch
      .mockReturnValueOnce(mockGitSuccess())        // git rebase --abort (proactive cleanup)
      .mockReturnValueOnce(mockPushSuccess());      // git push (done-state commit)

    const events: Record<string, unknown>[] = [];
    await handleMergedPrs(makeBaseOpts(wsRoot, {
      prResults: [makePrResult({ workspaceRoot: wsRoot, branchMissing: true })],
      emit: (e) => events.push(e),
    }));

    expect(lsRemoteCalled).toBe(true);
    expect(events.some((e) => e.type === "pr_merge_branch_recreated")).toBe(true);
    expect(events.some((e) => e.type === "task_marked_done")).toBe(true);
