    expect(events.some((e) => e.type === "workspace_pr_already_merged")).toBe(true);
    const curlCalls = vi.mocked(spawnSync).mock.calls.filter(([cmd]) => cmd === "curl");
    expect(curlCalls).toHaveLength(0);

    // YAML on disk should be done with workspace_pr.status = "merged"
    const updatedTask = parseYaml(
      readFileSync(join(wsRoot, "docs", "features", FEATURE_ID, "tasks", `${TASK_ID}.yaml`), "utf-8"),
    ) as Task;
    expect(updatedTask.status).toBe("done");
    expect(updatedTask.workspace_pr?.status).toBe("merged");
    expect(updatedTask.log.find((e) => e.action === "done")?.note).toContain("orphaned-branch recovery");
  });

  it("emits pr_merge_done_blocked when branch recreation itself fails", async () => {
    const task = makeTask();
    const wsRoot = makeWorkspaceWithTask(task);

    vi.mocked(execSync).mockImplementation((cmd) => {
