/**
 * Tests for poll/state-invariant-checker.ts
 *
 * Covers:
 *   1. Stuck dependent — todo task with all deps done is transitioned to ready
 *   2. Stuck handoff — all tasks done but no handoff → fireHandoffTrigger called
 *   3. Partial failure — one correction failing does not block others
 *   4. No violation — no git writes when everything is already consistent
 *   5. Stuck handoff skipped when githubToken absent
 */

import { describe, it, expect, vi, afterEach, beforeEach } from "vitest";
import {
  mkdtempSync,
  mkdirSync,
  writeFileSync,
  readFileSync,
  rmSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { parse as parseYaml, stringify as yamlStringify } from "yaml";
import { execSync, spawnSync } from "node:child_process";
import type { Task } from "../src/types/task.js";
import { fireHandoffTrigger } from "../src/handoff/handoff-trigger.js";
import { parseManagementRepoCoords } from "../src/config/workspace-config.js";
import { runStateInvariantCheck, type RunStateInvariantCheckOpts } from "../src/poll/state-invariant-checker.js";

// ── Mocks ─────────────────────────────────────────────────────────────────────

vi.mock("node:child_process", async (importOriginal) => {
  const actual = await importOriginal<typeof import("node:child_process")>();
  return { ...actual, execSync: vi.fn(), spawnSync: vi.fn() };
});

vi.mock("../src/handoff/handoff-trigger.js", () => ({
  fireHandoffTrigger: vi.fn().mockResolvedValue({ prUrl: "https://github.com/org/repo/pull/99" }),
}));

vi.mock("../src/config/workspace-config.js", async (importOriginal) => {
  const actual = await importOriginal<typeof import("../src/config/workspace-config.js")>();
  return {
    ...actual,
    parseManagementRepoCoords: vi.fn().mockReturnValue({
      owner: "test-org",
      repo: "test-workspace",
      baseBranch: "main",
    }),
  };
});

// ── Fixtures ──────────────────────────────────────────────────────────────────

const FEATURE_ID = "test-feature";
const GIT_AUTHOR_EMAIL = "agent@test.com";
const GIT_AUTHOR_NAME = "Agent Test";
