// ── Temp workspace helpers ────────────────────────────────────────────────────

const tmpDirs: string[] = [];

function makeWorkspace(featureId = FEATURE_ID): string {
  const dir = mkdtempSync(join(tmpdir(), "state-invariant-"));
  tmpDirs.push(dir);
  const tasksDir = join(dir, "docs", "features", featureId, "tasks");
  mkdirSync(tasksDir, { recursive: true });
