  }
  vi.clearAllMocks();
});

// ── 1. Stuck dependent is readied ─────────────────────────────────────────────

describe("runStateInvariantCheck — stuck dependent", () => {
  it("transitions todo task to ready when all deps are done", async () => {
    const wsRoot = makeWorkspace();
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { status: "todo", depends_on: ["T1"] });
    writeTask(wsRoot, t1);
    writeTask(wsRoot, t2);

    // execSync: fetch + ls-remote (branch found) + checkout + reset --hard + git add + git commit
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    // spawnSync: git push → success
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await runStateInvariantCheck(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "state_invariant_violation" && e.kind === "stuck_dependent")).toBe(true);
    expect(events.some((e) => e.type === "state_invariant_corrected" && e.kind === "stuck_dependent")).toBe(true);

    // YAML on disk: T2 should be updated to ready + log entry appended
    const updatedT2 = readTask(wsRoot, "T2");
    expect(updatedT2.status).toBe("ready");
    expect(updatedT2.log.some((e: { action: string }) => e.action === "ready")).toBe(true);
  });

  it("skips stuck-dependent correction when task branch is not on origin", async () => {
