    writeTask(wsRoot, t1);
    writeTask(wsRoot, t2);

    vi.mocked(execSync).mockImplementation((cmd) => {
      if (String(cmd).includes("ls-remote")) throw new Error("fatal: remote ref not found");
      return undefined as unknown as Buffer;
    });

