    await runStateInvariantCheck(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.some((e) => e.type === "state_invariant_correction_skipped" && e.kind === "stuck_dependent")).toBe(true);
    // T2 should still be todo since we skipped
    const t2After = readTask(wsRoot, "T2");
    expect(t2After.status).toBe("todo");
  });

  it("does not readie a todo task whose deps are not all done", async () => {
    const wsRoot = makeWorkspace();
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { status: "in_progress" as Task["status"] });
    // T3 depends on both T1 and T2 — T2 is still in_progress
    const t3 = makeTask("T3", { status: "todo", depends_on: ["T1", "T2"] });
    writeTask(wsRoot, t1);
    writeTask(wsRoot, t2);
    writeTask(wsRoot, t3);

