// ── 3. Partial failure does not block others ──────────────────────────────────

describe("runStateInvariantCheck — partial failure isolation", () => {
  it("continues processing other features when one feature throws", async () => {
    const wsRoot = makeWorkspace();
    const featureA = "feature-a";
    const featureB = "feature-b";

    // Feature A: has a stuck dependent — but git push will fail
    const a1 = makeTask("T1", { status: "done" });
    const a2 = makeTask("T2", { status: "todo", depends_on: ["T1"] });
    writeTask(wsRoot, a1, featureA);
    writeTask(wsRoot, a2, featureA);

    // Feature B: all tasks done, no handoff triggered
    const b1 = makeTask("T1", { status: "done" });
    writeTask(wsRoot, b1, featureB);
    writeStatusYaml(wsRoot, featureB, { feature_status: "in_implementation", handoff_pr_url: null });

    // git push fails for feature A, succeeds otherwise
    let pushCallCount = 0;
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockImplementation((cmd, args) => {
      const argStr = Array.isArray(args) ? args.join(" ") : "";
      if (String(cmd) === "git" && argStr.includes("push")) {
        pushCallCount++;
        if (pushCallCount === 1) return mockGitFailure("push rejected");
      }
      return mockGitSuccess();
    });

    vi.mocked(fireHandoffTrigger).mockResolvedValue({ prUrl: "https://github.com/org/repo/pull/99" });

    const events: Record<string, unknown>[] = [];
    await runStateInvariantCheck(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    // Feature A push failure should be recorded as a failed correction
    expect(events.some((e) => e.type === "state_invariant_correction_failed" && e.kind === "stuck_dependent")).toBe(true);

    // Feature B stuck handoff should still be processed despite feature A's failure
    expect(events.some((e) => e.type === "state_invariant_violation" && e.kind === "stuck_handoff")).toBe(true);
    expect(vi.mocked(fireHandoffTrigger)).toHaveBeenCalled();
  });

  it("continues processing other tasks when one stuck-dependent correction fails", async () => {
    const wsRoot = makeWorkspace();
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { status: "todo", depends_on: ["T1"] });
    const t3 = makeTask("T3", { status: "todo", depends_on: ["T1"] });
    writeTask(wsRoot, t1);
    writeTask(wsRoot, t2);
    writeTask(wsRoot, t3);

    let pushCallCount = 0;
    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockImplementation((cmd, args) => {
      const argStr = Array.isArray(args) ? args.join(" ") : "";
      if (String(cmd) === "git" && argStr.includes("push")) {
        pushCallCount++;
        if (pushCallCount === 1) return mockGitFailure("push rejected");
      }
      return mockGitSuccess();
    });

    const events: Record<string, unknown>[] = [];
    await runStateInvariantCheck(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    // Should have 2 violations detected
    const violations = events.filter((e) => e.type === "state_invariant_violation" && e.kind === "stuck_dependent");
    expect(violations).toHaveLength(2);

    // One failure, one success
    expect(events.some((e) => e.type === "state_invariant_correction_failed")).toBe(true);
    expect(events.some((e) => e.type === "state_invariant_corrected" && e.kind === "stuck_dependent")).toBe(true);
  });
});

// ── 4. No violations — no spurious git writes ─────────────────────────────────

describe("runStateInvariantCheck — no violations", () => {
  it("emits no violation events and does no git writes when everything is consistent", async () => {
    const wsRoot = makeWorkspace();
    const t1 = makeTask("T1", { status: "done" });
    const t2 = makeTask("T2", { status: "ready", depends_on: ["T1"] });
    writeTask(wsRoot, t1);
    writeTask(wsRoot, t2);
    writeStatusYaml(wsRoot, FEATURE_ID, { feature_status: "in_implementation", handoff_pr_url: null });

    vi.mocked(execSync).mockReturnValue(undefined as unknown as Buffer);
    vi.mocked(spawnSync).mockReturnValue(mockGitSuccess());

    const events: Record<string, unknown>[] = [];
    await runStateInvariantCheck(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events.filter((e) => e.type === "state_invariant_violation")).toHaveLength(0);
    expect(vi.mocked(fireHandoffTrigger)).not.toHaveBeenCalled();
  });

  it("is a no-op for empty features dir", async () => {
    const wsRoot = mkdtempSync(join(tmpdir(), "state-invariant-empty-"));
    tmpDirs.push(wsRoot);

    const events: Record<string, unknown>[] = [];
    await runStateInvariantCheck(makeOpts(wsRoot, { emit: (e) => events.push(e) }));

    expect(events).toHaveLength(0);
    expect(vi.mocked(execSync)).not.toHaveBeenCalled();
  });
});

// ── 5. Cycle-interval guard (documents the expected main.ts behavior) ─────────

describe("cycle-interval guard", () => {
  it("STATE_INVARIANT_CHECK_INTERVAL modulo arithmetic correctly gates cycles", () => {
    const interval = 5;
    const results: boolean[] = [];
    for (let cycle = 1; cycle <= 15; cycle++) {
      results.push(cycle % interval === 0);
    }
    // Only cycles 5, 10, 15 should trigger the check
    const triggeredCycles = results.map((r, i) => r ? i + 1 : null).filter(Boolean);
    expect(triggeredCycles).toEqual([5, 10, 15]);
  });
});

